insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Frações não computáveis: nas penas privativas de liberdade e restritivas de direitos desprezam-se as frações de dia, e na pena de multa as frações da unidade monetária.', '["Penas privativas de liberdade e restritivas de direitos: desprezam-se frações de dia.","Pena de multa: desprezam-se frações da moeda (o texto cita cruzeiro)."]'::jsonb, '["O artigo mantém a referência histórica ao cruzeiro; a ideia é desprezar frações da unidade monetária."]'::jsonb, 'Ao diminuir a pena e sobrar fração de dia, ela é desprezada.', '["Assertiva que manda arredondar para cima as frações de dia contraria o art. 11, que as despreza."]'::jsonb, '[]'::jsonb, '["Art. 10 (contagem de prazo)"]'::jsonb, 'under_review', 'claude'
