insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Legislação especial: as regras gerais do Código Penal aplicam-se aos fatos incriminados por lei especial, se esta não dispuser de modo diverso (princípio da especialidade).', '["Regras gerais do Código valem para leis especiais.","Exceção: se a lei especial dispuser de modo diverso."]'::jsonb, '["Prevalece a lei especial quando ela trata do tema de forma diferente."]'::jsonb, 'Em um crime previsto em lei extravagante, aplicam-se as regras sobre tentativa e concurso de pessoas do Código, se a lei não disser o contrário.', '["Assertiva que afasta a parte geral do Código Penal de qualquer lei especial erra: ela se aplica se a lei especial não dispuser diferente."]'::jsonb, '[{"termo":"Lei especial","significado":"Lei que trata de matéria específica fora do Código."}]'::jsonb, '[]'::jsonb, 'under_review', 'claude'
