insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Efeitos da condenação: tornar certa a obrigação de indenizar o dano causado pelo crime e a perda em favor da União, ressalvado o direito do lesado ou de terceiro de boa-fé, dos instrumentos do crime (se consistirem em coisas cujo fabrico, alienação, uso, porte ou detenção seja ilícito) e do produto do crime ou de qualquer bem ou valor que constitua proveito auferido com o crime. O §1º permite a perda de bens ou valores equivalentes quando o produto não for encontrado ou estiver no exterior, e o §2º estende as medidas assecuratórias a bens equivalentes. O texto traz ''Vide ADPF 569''.', '["I – torna certa a obrigação de indenizar o dano.","II, a: perda dos instrumentos do crime cujo fabrico, alienação, uso, porte ou detenção seja ilícito.","II, b: perda do produto do crime ou de qualquer bem ou valor que constitua proveito.","Ressalva: direito do lesado ou de terceiro de boa-fé.","§1º: perda de bens ou valores equivalentes se não encontrados ou no exterior.","§2º: medidas assecuratórias podem alcançar bens equivalentes."]'::jsonb, '["Os instrumentos só são confiscados se forem coisas ilícitas em si (fabrico, alienação, uso, porte ou detenção).","A perda é em favor da UNIÃO, ressalvado o lesado ou terceiro de boa-fé."]'::jsonb, 'A arma sem registro usada no crime é perdida em favor da União após a condenação.', '["Assertiva que confisca qualquer instrumento do crime, ainda que de uso lícito, erra: só os de fabrico, alienação, uso, porte ou detenção ilícitos."]'::jsonb, '[{"termo":"Medidas assecuratórias","significado":"Medidas cautelares para garantir bens, como o sequestro."}]'::jsonb, '["Art. 91-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-91'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Perda alargada: na condenação por infrações com pena máxima superior a 6 anos de reclusão, pode ser decretada a perda, como produto ou proveito do crime, dos bens correspondentes à diferença entre o valor do patrimônio do condenado e o que seja compatível com seu rendimento lícito. Considera-se patrimônio todos os bens de sua titularidade ou sobre os quais tenha domínio e benefício, e os transferidos a terceiros a título gratuito ou por contraprestação irrisória desde o início da atividade criminal. O condenado pode demonstrar a origem lícita; a perda deve ser requerida expressamente pelo Ministério Público na denúncia, com indicação da diferença apurada.', '["Cabimento: infrações com pena máxima superior a 6 anos de reclusão.","Objeto: diferença entre o patrimônio e o rendimento lícito.","§1º: patrimônio inclui bens titulados, de domínio e benefício, e os transferidos a terceiros gratuitamente ou por valor irrisório.","§2º: o condenado pode demonstrar a origem lícita.","§3º: requerimento expresso do MP na denúncia, com a diferença apurada."]'::jsonb, '["Pena MÁXIMA superior a 6 anos (não a pena aplicada).","A perda deve ser pedida pelo MP na denúncia."]'::jsonb, 'Condenado por crime com pena máxima de 10 anos tem patrimônio muito acima do rendimento lícito: o excedente pode ser perdido, se o MP requereu na denúncia.', '["Assertiva que dispensa o requerimento expresso do Ministério Público na denúncia erra: o §3º o exige."]'::jsonb, '[{"termo":"Perda alargada","significado":"Confisco da diferença entre o patrimônio e o rendimento lícito do condenado."}]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-91-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Efeitos específicos da condenação (não são automáticos: dependem de declaração motivada na sentença). I: perda de cargo, função pública ou mandato eletivo quando aplicada pena privativa de liberdade igual ou superior a 1 ano nos crimes praticados com abuso de poder ou violação de dever para com a Administração Pública, ou superior a 4 anos nos demais casos. II: incapacidade para o poder familiar, tutela ou curatela nos crimes dolosos sujeitos à pena de reclusão contra outrem igualmente titular do mesmo poder, contra filho, descendente, tutelado ou curatelado e nos crimes contra a mulher por razões da condição do sexo feminino. III: inabilitação para dirigir veículo quando utilizado como meio para crime doloso. O inciso IV traz regra de suspensão da inscrição no CNPJ de estabelecimento (confira o texto completo).', '["I, a: perda do cargo se pena igual ou superior a 1 ano, em crime com abuso de poder ou violação de dever para com a Administração.","I, b: perda do cargo se pena superior a 4 anos nos demais casos.","II: incapacidade para poder familiar, tutela ou curatela em crimes dolosos de reclusão contra familiar/tutelado ou contra a mulher por razões da condição do sexo feminino.","III: inabilitação para dirigir quando o veículo é meio para crime DOLOSO.","IV: suspensão da inscrição no CNPJ por 180 dias, nos termos do texto."]'::jsonb, '["Limites do inciso I: 1 ano (crimes funcionais) e MAIS DE 4 anos (demais).","Os efeitos do art. 92 não são automáticos: devem ser motivadamente declarados na sentença (regra do parágrafo único do artigo, conforme o texto completo).","Inabilitação para dirigir: crime doloso (para culposo de trânsito, veja o art. 47, III)."]'::jsonb, 'Servidor condenado a 2 anos por peculato pode perder o cargo (inciso I, a).', '["Assertiva que exige pena superior a 4 anos para a perda do cargo nos crimes praticados com abuso de poder erra: basta pena igual ou superior a 1 ano."]'::jsonb, '[]'::jsonb, '["Art. 93 (reabilitação)","Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-92'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A reabilitação alcança quaisquer penas aplicadas em sentença definitiva, assegurando ao condenado o sigilo dos registros sobre seu processo e condenação. Pode também atingir os efeitos da condenação do art. 92, vedada a reintegração na situação anterior nos casos dos incisos I e II.', '["Alcança quaisquer penas aplicadas em sentença definitiva.","Assegura sigilo dos registros do processo e da condenação.","Pode atingir os efeitos do art. 92, mas sem reintegração nos casos dos incisos I e II."]'::jsonb, '["Mesmo reabilitado, não volta ao cargo perdido nem recupera o poder familiar (art. 92, I e II)."]'::jsonb, 'O reabilitado tem o sigilo dos registros, mas o servidor que perdeu o cargo não é reintegrado.', '["Assertiva que garante reintegração ao cargo perdido pela reabilitação erra: é vedada."]'::jsonb, '[{"termo":"Reabilitação","significado":"Medida que assegura o sigilo da condenação e pode afastar certos efeitos dela."}]'::jsonb, '["Art. 92","Art. 94"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-93'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A reabilitação pode ser requerida decorridos 2 anos do dia em que for extinta, de qualquer modo, a pena ou terminar sua execução, computando-se o período de prova da suspensão e do livramento condicional se não houver revogação, desde que o condenado: tenha tido domicílio no País nesse prazo; demonstre bom comportamento público e privado; e tenha ressarcido o dano (ou demonstre a absoluta impossibilidade) ou exiba renúncia da vítima ou novação da dívida. Negada, pode ser requerida novamente a qualquer tempo, com novos elementos.', '["Prazo: 2 anos após a extinção ou término da execução da pena.","I – domicílio no País durante o prazo.","II – bom comportamento público e privado, de forma efetiva e constante.","III – dano ressarcido (ou absoluta impossibilidade), ou renúncia da vítima/novação da dívida.","Parágrafo único: negada, pode ser requerida de novo com novos elementos comprobatórios."]'::jsonb, '["Prazo de 2 anos (conte o período de prova do sursis e do livramento se não revogados).","Três requisitos cumulativos: domicílio, bom comportamento e reparação."]'::jsonb, 'Dois anos depois do término da pena, o condenado que comprovou bom comportamento e ressarciu o dano pede a reabilitação.', '["Assertiva que fixa o prazo da reabilitação em 5 anos erra: é de 2 anos."]'::jsonb, '[]'::jsonb, '["Arts. 93 e 95"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-94'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A reabilitação será revogada, de ofício ou a requerimento do Ministério Público, se o reabilitado for condenado, como reincidente, por decisão definitiva, a pena que não seja de multa.', '["Revogação de ofício ou a requerimento do MP.","Condenação como reincidente, por decisão definitiva, a pena que não seja de multa."]'::jsonb, '["Condenação só a multa NÃO revoga a reabilitação."]'::jsonb, 'O reabilitado volta a ser condenado, como reincidente, a prisão: a reabilitação é revogada.', '["Assertiva que revoga a reabilitação por condenação apenas a multa contraria o art. 95."]'::jsonb, '[]'::jsonb, '["Arts. 93 e 94"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-95'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de segurança são a internação em hospital de custódia e tratamento psiquiátrico (ou, à falta, em outro estabelecimento adequado) e a sujeição a tratamento ambulatorial. Extinta a punibilidade, não se impõe medida de segurança nem subsiste a que tenha sido imposta.', '["I – internação em hospital de custódia e tratamento psiquiátrico ou estabelecimento adequado.","II – tratamento ambulatorial.","Extinta a punibilidade: não se impõe nem subsiste a medida."]'::jsonb, '["As medidas de segurança são duas espécies: internação e tratamento ambulatorial."]'::jsonb, 'O inimputável que praticou fato típico e ilícito pode ser internado ou sujeito a tratamento ambulatorial.', '["Assertiva que mantém a medida de segurança mesmo após extinta a punibilidade contraria o parágrafo único."]'::jsonb, '[{"termo":"Medida de segurança","significado":"Medida de cunho curativo aplicada a inimputáveis (ou semi-imputáveis em certos casos)."}]'::jsonb, '["Art. 97","Art. 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-96'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o agente for inimputável, o juiz determina sua internação; se o fato for punível com detenção, pode submetê-lo a tratamento ambulatorial. A internação ou o tratamento é por tempo indeterminado, enquanto não for averiguada, por perícia médica, a cessação da periculosidade, com prazo mínimo de 1 a 3 anos. A perícia ocorre ao fim do prazo mínimo e deve ser repetida de ano em ano, ou a qualquer tempo se o juiz da execução determinar. A desinternação ou liberação é sempre condicional e a situação anterior é restabelecida se, antes de 1 ano, o agente pratica fato indicativo de persistência da periculosidade. Em qualquer fase do tratamento ambulatorial, o juiz pode determinar a internação, se necessária para fins curativos.', '["Inimputável: internação; se o fato é punível com detenção, o juiz pode aplicar tratamento ambulatorial.","§1º: tempo indeterminado, até cessar a periculosidade; prazo mínimo de 1 a 3 anos.","§2º: perícia ao fim do prazo mínimo e repetida de ano em ano.","§3º: desinternação/liberação sempre condicional; restabelece-se a situação anterior se, antes de 1 ano, houver fato indicativo de periculosidade.","§4º: o juiz pode converter o ambulatorial em internação, se necessário para fins curativos."]'::jsonb, '["Prazo MÍNIMO de 1 a 3 anos e MÁXIMO indeterminado (o tema do limite é muito cobrado, conforme a jurisprudência).","A desinternação é CONDICIONAL: período de 1 ano."]'::jsonb, 'Inimputável que cometeu crime punido com reclusão é internado; a internação dura enquanto houver periculosidade, com perícia anual após o prazo mínimo.', '["Assertiva que fixa prazo máximo definitivo de 3 anos para a medida de segurança lê o prazo MÍNIMO como máximo: o texto fala em tempo indeterminado."]'::jsonb, '[{"termo":"Periculosidade","significado":"Probabilidade de o agente voltar a delinquir, que justifica a medida de segurança."}]'::jsonb, '["Art. 26","Art. 96","Art. 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-97'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na hipótese do parágrafo único do art. 26 (semi-imputável) e necessitando o condenado de especial tratamento curativo, a pena privativa de liberdade pode ser substituída pela internação ou tratamento ambulatorial, pelo prazo mínimo de 1 a 3 anos, nos termos do art. 97 e dos §§1º a 4º.', '["Aplica-se ao semi-imputável que necessite de especial tratamento curativo.","A pena privativa pode ser substituída por internação ou tratamento ambulatorial.","Prazo mínimo de 1 a 3 anos, nos termos do art. 97."]'::jsonb, '["É o sistema vicariante: pena OU medida de segurança, não as duas."]'::jsonb, 'Condenado semi-imputável que precisa de tratamento tem a prisão substituída por internação.', '["Assertiva que cumula pena e medida de segurança para o semi-imputável contraria o art. 98 (substitui)."]'::jsonb, '[{"termo":"Sistema vicariante","significado":"Pena ou medida de segurança, nunca as duas ao mesmo tempo."}]'::jsonb, '["Art. 26, parágrafo único","Art. 97"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-98'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O internado será recolhido a estabelecimento dotado de características hospitalares e será submetido a tratamento.', '["Estabelecimento com características hospitalares.","Submetido a tratamento."]'::jsonb, '["A internação tem finalidade curativa, não punitiva."]'::jsonb, 'O inimputável internado fica em hospital de custódia e recebe tratamento.', '["Assertiva que determina recolhimento do internado em presídio comum contraria o art. 99."]'::jsonb, '[]'::jsonb, '["Arts. 96 a 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-99'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ação penal: a ação é pública, salvo quando a lei expressamente a declara privativa do ofendido. A ação pública é promovida pelo Ministério Público, dependendo, quando a lei o exige, de representação do ofendido ou de requisição do Ministro da Justiça. A ação de iniciativa privada é promovida por queixa do ofendido ou de quem o represente e pode ser intentada nos crimes de ação pública se o Ministério Público não oferecer denúncia no prazo legal (ação privada subsidiária). Em caso de morte do ofendido ou declaração de ausência, o direito de queixa ou de prosseguir passa ao cônjuge, ascendente, descendente ou irmão.', '["Regra: ação penal pública; exceção: privativa do ofendido, se a lei declarar.","§1º: pública promovida pelo MP; pode depender de representação ou requisição do Ministro da Justiça.","§2º: privada promovida por queixa.","§3º: ação privada subsidiária da pública, se o MP não denunciar no prazo legal.","§4º: morte ou ausência do ofendido: o direito passa a cônjuge, ascendente, descendente ou irmão."]'::jsonb, '["A regra é ação PÚBLICA; a privada precisa de previsão expressa.","Ordem de sucessão no §4º: cônjuge, ascendente, descendente ou irmão (conforme o texto)."]'::jsonb, 'O Ministério Público deixa de denunciar no prazo legal em crime de ação pública: o ofendido pode propor queixa subsidiária.', '["Assertiva que torna regra a ação privada erra: a regra é a ação pública."]'::jsonb, '[{"termo":"Queixa","significado":"Petição inicial da ação penal privada."},{"termo":"Representação","significado":"Manifestação da vítima autorizando o MP a processar em certos crimes."}]'::jsonb, '["Arts. 101 a 106"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-100'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime complexo: quando a lei considera como elemento ou circunstância do tipo legal fatos que, por si mesmos, constituem crimes, cabe ação pública em relação àquele, desde que, em relação a qualquer destes, se deva proceder por iniciativa do Ministério Público.', '["Fatos que integram o tipo e são crimes por si mesmos.","Cabe ação pública no crime complexo se algum deles for de ação pública."]'::jsonb, '["Prevalece a ação pública se qualquer dos crimes componentes é de ação pública."]'::jsonb, 'O roubo é complexo (furto + violência ou ameaça); como alguns de seus componentes são de ação pública, a ação é pública.', '["Assertiva que torna privada a ação do crime complexo apenas porque um componente é de ação privada, mesmo havendo componente de ação pública, contraria o art. 101."]'::jsonb, '[{"termo":"Crime complexo","significado":"Crime formado pela fusão de dois ou mais outros crimes ou fatos típicos."}]'::jsonb, '["Art. 100"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-101'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A representação da vítima, que autoriza o Ministério Público a agir nos crimes de ação pública condicionada, pode ser retirada (retratação) até o oferecimento da denúncia; depois disso, ela é irretratável.', '["A representação pode ser retratada até o oferecimento da denúncia.","Depois da denúncia, é irretratável."]'::jsonb, '["O marco é o OFERECIMENTO da denúncia."]'::jsonb, 'A vítima que ofereceu representação pode se retratar antes de o MP denunciar; depois, não.', '["Assertiva que permite a retratação da representação após o recebimento da denúncia erra: o marco é o oferecimento."]'::jsonb, '[{"termo":"Irretratável","significado":"Que não pode mais ser desfeita ou retirada."}]'::jsonb, '["Art. 100, §1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-102'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo disposição expressa em contrário, o ofendido decai do direito de queixa ou de representação se não o exerce dentro de 6 meses, contados do dia em que veio a saber quem é o autor do crime, ou, no caso da ação privada subsidiária, do dia em que se esgota o prazo para o oferecimento da denúncia. Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, o prazo é de 12 meses, conforme o parágrafo único (incluído por lei de 2026).', '["Prazo decadencial: 6 meses, da ciência de quem é o autor.","Ação privada subsidiária: conta-se do fim do prazo para a denúncia.","Parágrafo único: violência doméstica e familiar contra a mulher: 12 meses."]'::jsonb, '["O prazo conta da ciência de QUEM É O AUTOR, não da data do fato.","Violência doméstica e familiar contra a mulher: prazo de 12 meses (conforme o texto atual)."]'::jsonb, 'A vítima soube quem era o autor em janeiro: tem até julho para exercer a queixa ou a representação (regra geral).', '["Assertiva que conta o prazo de 6 meses do dia do fato erra: conta-se da ciência de quem é o autor."]'::jsonb, '[{"termo":"Decadência","significado":"Perda do direito pelo decurso do prazo para exercê-lo."}]'::jsonb, '["Art. 100","Art. 107, IV"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-103'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito de queixa não pode ser exercido quando renunciado expressa ou tacitamente. Importa renúncia tácita a prática de ato incompatível com a vontade de exercê-lo; não a implica o fato de o ofendido receber a indenização do dano causado pelo crime.', '["Renúncia expressa ou tácita impede a queixa.","Renúncia tácita: ato incompatível com a vontade de exercê-la.","Receber a indenização do dano NÃO implica renúncia."]'::jsonb, '["Receber indenização não significa renúncia ao direito de queixa."]'::jsonb, 'Quem convida o ofensor para um evento familiar pode ter praticado ato incompatível com a intenção de processá-lo (renúncia tácita).', '["Assertiva que considera renúncia tácita o simples recebimento da indenização do dano erra."]'::jsonb, '[]'::jsonb, '["Art. 105","Art. 107, V"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-104'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O perdão do ofendido, nos crimes em que somente se procede mediante queixa, obsta ao prosseguimento da ação.', '["O perdão do ofendido obsta o prosseguimento da ação privada."]'::jsonb, '["Só nos crimes de ação PRIVADA; precisa ser aceito (art. 107, V)."]'::jsonb, 'No curso da ação privada, o ofendido perdoa o querelado, que aceita: a ação não prossegue.', '["Assertiva que aplica o perdão do ofendido à ação penal pública incondicionada erra."]'::jsonb, '[{"termo":"Querelado","significado":"Réu na ação penal privada."}]'::jsonb, '["Art. 106","Art. 107, V"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-105'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regras do perdão, no processo ou fora dele, expresso ou tácito: se concedido a qualquer dos querelados, a todos aproveita; se concedido por um dos ofendidos, não prejudica o direito dos outros; se o querelado o recusa, não produz efeito. Perdão tácito é o que resulta de ato incompatível com a vontade de prosseguir na ação. Não é admissível depois do trânsito em julgado da sentença condenatória.', '["I – perdão a um querelado aproveita a todos.","II – perdão de um ofendido não prejudica os demais.","III – recusado pelo querelado, não produz efeito.","§1º: perdão tácito = ato incompatível com a vontade de prosseguir.","§2º: não cabe depois do trânsito em julgado da condenação."]'::jsonb, '["O perdão precisa ser ACEITO pelo querelado.","Limite temporal: antes do trânsito em julgado da condenação."]'::jsonb, 'Perdoado um dos querelados em ação privada, todos são beneficiados, salvo recusa.', '["Assertiva que admite o perdão após o trânsito em julgado da condenação contraria o §2º."]'::jsonb, '[]'::jsonb, '["Art. 105"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-106'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Rol de causas de extinção da punibilidade: morte do agente; anistia, graça ou indulto; retroatividade de lei que não mais considera o fato criminoso; prescrição, decadência ou perempção; renúncia do direito de queixa ou perdão aceito nos crimes de ação privada; retratação do agente nos casos em que a lei a admite; e perdão judicial nos casos previstos em lei. Os incisos VII e VIII estão revogados.', '["I – morte do agente.","II – anistia, graça ou indulto.","III – abolitio criminis.","IV – prescrição, decadência ou perempção.","V – renúncia ao direito de queixa ou perdão aceito (ação privada).","VI – retratação do agente, nos casos admitidos em lei.","IX – perdão judicial, nos casos previstos em lei.","VII e VIII: revogados."]'::jsonb, '["O rol do art. 107 NÃO é taxativo (outras leis preveem causas de extinção).","Perdão do ofendido só extingue se ACEITO e na ação privada."]'::jsonb, 'Com a morte do agente, extingue-se a punibilidade.', '["Assertiva que afirma que o rol do art. 107 é taxativo erra: existem outras causas em leis especiais."]'::jsonb, '[{"termo":"Punibilidade","significado":"Possibilidade jurídica de o Estado punir o agente."}]'::jsonb, '["Arts. 108 a 120"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-107'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A extinção da punibilidade de crime que é pressuposto, elemento constitutivo ou circunstância agravante de outro não se estende a este. Nos crimes conexos, a extinção da punibilidade de um deles não impede, quanto aos outros, a agravação da pena resultante da conexão.', '["Extinção da punibilidade do crime-pressuposto não se estende ao outro.","Em crimes conexos, a extinção de um não impede a agravação nos outros."]'::jsonb, '["Cada crime tem sua punibilidade analisada de forma independente."]'::jsonb, 'Extinta a punibilidade do furto anterior, o receptador ainda pode responder pela receptação.', '["Assertiva que estende a extinção da punibilidade de um crime ao outro de que é pressuposto contraria o art. 108."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-108'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prescrição da pretensão punitiva antes do trânsito em julgado: regula-se pelo máximo da pena privativa de liberdade cominada ao crime (salvo o §1º do art. 110) e ocorre em 20 anos se o máximo é superior a 12; 16 anos se superior a 8 e não excede 12; 12 anos se superior a 4 e não excede 8; 8 anos se superior a 2 e não excede 4; 4 anos se igual a 1 ou, sendo superior, não excede 2; e 3 anos se inferior a 1. As penas restritivas de direitos prescrevem nos mesmos prazos das privativas.', '["Base: máximo da pena PRIVATIVA DE LIBERDADE COMINADA ao crime.","Superior a 12 anos: 20 anos.","Superior a 8 e até 12: 16 anos.","Superior a 4 e até 8: 12 anos.","Superior a 2 e até 4: 8 anos.","Igual a 1 ou, sendo superior, até 2: 4 anos.","Inferior a 1 ano: 3 anos.","Parágrafo único: restritivas de direitos têm os mesmos prazos."]'::jsonb, '["A tabela do art. 109 é o item mais cobrado de prescrição: decore os escalões.","Antes do trânsito: regula-se pela pena MÁXIMA em abstrato; depois, pela pena aplicada (art. 110)."]'::jsonb, 'Crime com pena máxima de 6 anos prescreve em 12 anos (inciso III).', '["Assertiva que fixa em 16 anos a prescrição de crime com pena máxima de 6 anos erra: o prazo é de 12 anos."]'::jsonb, '[{"termo":"Prescrição da pretensão punitiva","significado":"Perda do direito de punir pelo tempo decorrido antes da condenação definitiva."}]'::jsonb, '["Art. 110","Art. 111","Art. 115"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-109'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prescrição depois do trânsito em julgado da sentença condenatória: regula-se pela pena aplicada e verifica-se nos prazos do art. 109, aumentados de um terço se o condenado é reincidente. O §1º: depois da sentença condenatória com trânsito em julgado para a acusação ou improvido seu recurso, regula-se pela pena aplicada, não podendo ter por termo inicial data anterior à da denúncia ou queixa. O §2º foi revogado.', '["Regula-se pela pena aplicada, nos prazos do art. 109.","Reincidente: prazos aumentados de 1/3 (apenas na prescrição da pretensão executória).","§1º: trânsito para a acusação ou recurso improvido: pela pena aplicada; termo inicial não pode ser anterior à denúncia ou queixa."]'::jsonb, '["O aumento de 1/3 pela reincidência vale para a prescrição DEPOIS da condenação definitiva.","O termo inicial não retroage a data anterior à denúncia ou queixa (§1º)."]'::jsonb, 'Condenado reincidente a pena de 3 anos: o prazo do art. 109, IV (8 anos) é aumentado em um terço.', '["Assertiva que aplica o aumento de 1/3 pela reincidência à prescrição antes da sentença erra: vale após o trânsito em julgado."]'::jsonb, '[{"termo":"Prescrição da pretensão executória","significado":"Perda do direito de executar a pena após a condenação definitiva."}]'::jsonb, '["Art. 109","Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-110'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Termo inicial da prescrição antes do trânsito em julgado: começa a correr do dia em que o crime se consumou; na tentativa, do dia em que cessou a atividade criminosa; nos crimes permanentes, do dia em que cessou a permanência; na bigamia e na falsificação ou alteração de assentamento do registro civil, da data em que o fato se tornou conhecido; e, nos crimes contra a dignidade sexual ou que envolvam violência contra a criança e o adolescente, da data em que a vítima completar 18 anos, salvo se a ação penal já tiver sido proposta.', '["I – consumação.","II – tentativa: cessação da atividade criminosa.","III – crime permanente: cessação da permanência.","IV – bigamia e falsificação de registro civil: quando o fato se tornou conhecido.","V – crimes sexuais e contra criança e adolescente: quando a vítima completar 18 anos, salvo ação já proposta."]'::jsonb, '["Para a prescrição, o termo inicial é a CONSUMAÇÃO (diferente do tempo do crime, art. 4º).","No inciso V, o termo é o 18º aniversário da vítima (se a ação ainda não foi proposta)."]'::jsonb, 'Em crime permanente, como o sequestro, a prescrição só começa quando a vítima é libertada.', '["Assertiva que fixa o termo inicial da prescrição no momento da ação, e não da consumação, erra."]'::jsonb, '[]'::jsonb, '["Art. 109","Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-111'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso do art. 110 (prescrição depois da condenação), a prescrição começa a correr: do dia em que transita em julgado a sentença condenatória para a acusação, ou a que revoga a suspensão condicional da pena ou o livramento condicional; ou do dia em que se interrompe a execução, salvo quando o tempo da interrupção deva computar-se na pena.', '["I – trânsito em julgado da condenação para a acusação, ou decisão que revoga o sursis ou o livramento.","II – dia em que se interrompe a execução, salvo se o tempo da interrupção é computado na pena."]'::jsonb, '["O marco é o trânsito para a ACUSAÇÃO (não para a defesa)."]'::jsonb, 'A condenação transita em julgado para o MP em março: a prescrição da pretensão executória começa nessa data.', '["Assertiva que inicia a prescrição executória do trânsito para a defesa erra: é para a acusação."]'::jsonb, '[]'::jsonb, '["Art. 110"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-112'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de evadir-se o condenado ou de revogar-se o livramento condicional, a prescrição é regulada pelo tempo que resta da pena.', '["Fuga do condenado ou revogação do livramento: prescrição regulada pelo tempo que resta da pena."]'::jsonb, '["Calcula-se pelo tempo RESTANTE, não pela pena total."]'::jsonb, 'O condenado foge com 2 anos de pena por cumprir: a prescrição considera esses 2 anos restantes.', '["Assertiva que usa a pena total na prescrição após a fuga erra: usa o tempo que resta."]'::jsonb, '[]'::jsonb, '["Art. 110"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-113'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prescrição da multa: ocorre em 2 anos quando a multa for a única cominada ou aplicada; e no mesmo prazo da prescrição da pena privativa de liberdade quando a multa for alternativa ou cumulativamente cominada ou cumulativamente aplicada.', '["I – 2 anos: multa única (cominada ou aplicada).","II – mesmo prazo da privativa: multa alternativa, ou cumulativa (cominada ou aplicada)."]'::jsonb, '["Multa isolada: 2 anos; multa junto com prisão: prazo da prisão."]'::jsonb, 'Contravenção punida só com multa prescreve em 2 anos.', '["Assertiva que fixa em 5 anos a prescrição da multa única erra: são 2 anos."]'::jsonb, '[]'::jsonb, '["Art. 109"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-114'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São reduzidos de metade os prazos de prescrição quando o criminoso era, ao tempo do crime, menor de 21 anos ou, na data da sentença, maior de 70 anos, salvo se o crime envolver violência sexual contra a mulher (redação de 2025).', '["Redução pela metade dos prazos de prescrição.","Menor de 21 anos ao tempo do crime ou maior de 70 na data da sentença.","Exceção: crime com violência sexual contra a mulher."]'::jsonb, '["Menor de 21: ao tempo do CRIME; maior de 70: na data da SENTENÇA.","Há exceção para violência sexual contra a mulher (texto atual)."]'::jsonb, 'Agente de 20 anos ao tempo do fato tem os prazos de prescrição reduzidos à metade.', '["Assertiva que considera a idade de 70 anos na data do crime erra: é na data da sentença."]'::jsonb, '[]'::jsonb, '["Art. 65, I","Art. 109"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-115'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Causas impeditivas da prescrição: antes do trânsito em julgado, a prescrição não corre enquanto não resolvida, em outro processo, questão de que dependa o reconhecimento do crime; enquanto o agente cumpre pena no exterior; na pendência de embargos de declaração ou de recursos aos Tribunais Superiores, quando inadmissíveis; e enquanto não cumprido ou não rescindido o acordo de não persecução penal. Depois do trânsito em julgado da condenação, a prescrição não corre enquanto o condenado está preso por outro motivo.', '["I – questão prejudicial resolvida em outro processo.","II – cumprimento de pena no exterior.","III – embargos de declaração ou recursos aos Tribunais Superiores inadmissíveis.","IV – acordo de não persecução penal não cumprido ou não rescindido.","Parágrafo único: após o trânsito, não corre enquanto o condenado está preso por outro motivo."]'::jsonb, '["Impedir é SUSPENDER o prazo (ele volta a correr de onde parou).","Os recursos só impedem a prescrição quando INADMISSÍVEIS."]'::jsonb, 'Enquanto o agente cumpre pena no exterior, a prescrição do crime no Brasil não corre.', '["Assertiva que trata como interruptivas as causas do art. 116 erra: elas são impeditivas (suspendem)."]'::jsonb, '[]'::jsonb, '["Art. 117"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-116'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Causas interruptivas da prescrição: o curso da prescrição se interrompe pelo recebimento da denúncia ou da queixa; pela pronúncia; pela decisão confirmatória da pronúncia; pela publicação da sentença ou acórdão condenatórios recorríveis; pelo início ou continuação do cumprimento da pena; e pela reincidência. Salvo os incisos V e VI, a interrupção produz efeitos relativamente a todos os autores do crime, e nos crimes conexos do mesmo processo estende-se aos demais. Interrompida a prescrição, salvo no inciso V, todo o prazo começa a correr de novo.', '["I – recebimento da denúncia ou da queixa.","II – pronúncia.","III – decisão confirmatória da pronúncia.","IV – publicação de sentença ou acórdão condenatórios recorríveis.","V – início ou continuação do cumprimento da pena.","VI – reincidência.","§1º: exceto V e VI, a interrupção vale para todos os autores; nos crimes conexos, estende-se aos demais.","§2º: interrompida, o prazo recomeça INTEIRO (salvo no inciso V)."]'::jsonb, '["INTERROMPER zera o prazo; IMPEDIR/SUSPENDER apenas congela.","Os incisos V e VI interrompem só em relação ao agente."]'::jsonb, 'O recebimento da denúncia interrompe a prescrição e o prazo recomeça por inteiro.', '["Assertiva que afirma que a interrupção apenas suspende o prazo, que depois retoma de onde parou, erra: o prazo começa a correr novamente por inteiro."]'::jsonb, '[]'::jsonb, '["Art. 116","Art. 109"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-117'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a pena mais grave prescreve, as penas mais leves prescrevem junto com ela: a prescrição da pena principal alcança as penas menos graves que a acompanham.', '["A prescrição da pena mais grave leva a das mais leves."]'::jsonb, '["Vale a lógica de que a pena menos grave não sobrevive à mais grave."]'::jsonb, 'Prescrita a pena de prisão, a de multa cumulada também prescreve.', '["Assertiva que mantém a pena mais leve após a prescrição da mais grave contraria o art. 118."]'::jsonb, '[]'::jsonb, '["Art. 114"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-118'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No concurso de crimes, a extinção da punibilidade incidirá sobre a pena de cada um, isoladamente.', '["A extinção da punibilidade, no concurso, é analisada crime a crime."]'::jsonb, '["A prescrição não considera a pena total do concurso, e sim a pena de cada crime."]'::jsonb, 'Em concurso de dois crimes, a prescrição de cada um é contada pela pena de cada um, e não pelo somatório.', '["Assertiva que calcula a prescrição pela soma das penas do concurso contraria o art. 119."]'::jsonb, '[]'::jsonb, '["Arts. 69 a 71","Art. 109"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-119'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença que concede o perdão judicial não será considerada para efeitos de reincidência.', '["O perdão judicial não gera reincidência."]'::jsonb, '["Perdão judicial é causa de extinção da punibilidade (art. 107, IX) e a sentença que o concede não é condenatória para efeito de reincidência."]'::jsonb, 'Quem recebeu perdão judicial e depois comete novo crime não é reincidente por aquele fato.', '["Assertiva que considera reincidente quem obteve perdão judicial anterior contraria o art. 120."]'::jsonb, '[{"termo":"Perdão judicial","significado":"Dispensa de pena concedida pelo juiz nos casos previstos em lei."}]'::jsonb, '["Art. 107, IX","Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-120'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Homicídio: matar alguém, com pena de reclusão de 6 a 20 anos. Há formas privilegiada (redução de um sexto a um terço se o agente age por relevante valor social ou moral, ou sob violenta emoção logo em seguida a injusta provocação da vítima), qualificada (reclusão de 12 a 30 anos, nos casos do §2º), culposa (detenção de 1 a 3 anos) e várias causas de aumento. Nas qualificadoras estão: paga, promessa de recompensa ou outro motivo torpe; motivo fútil; veneno, fogo, explosivo, asfixia, tortura ou meio insidioso, cruel ou de perigo comum; traição, emboscada, dissimulação ou recurso que dificulte ou impossibilite a defesa; para assegurar execução, ocultação, impunidade ou vantagem de outro crime; contra autoridades e agentes de segurança pública, do sistema prisional, membros do Judiciário, MP, Defensoria, Advocacia Pública e oficial de justiça (e seus familiares) em razão da função; arma de fogo de uso restrito ou proibido; contra menor de 14 anos; e nas dependências de instituição de ensino.', '["Caput: reclusão de 6 a 20 anos.","§1º (privilégio): relevante valor social ou moral, ou violenta emoção logo após injusta provocação: redução de um sexto a um terço.","§2º (qualificado): reclusão de 12 a 30 anos. Incisos I a V (motivos e meios) e VII a X (vítimas e circunstâncias especiais); o inciso VI foi revogado (feminicídio agora no art. 121-A).","§2º-B e §2º-C: causas de aumento para homicídio contra menor de 14 anos e nas dependências de instituição de ensino.","§2º-D: homicídio doloso por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada: reclusão de 20 a 40 anos (texto atual).","§3º: homicídio culposo: detenção de 1 a 3 anos.","§4º: culposo, aumento de 1/3 se inobservância de regra técnica, ou se o agente deixa de prestar socorro, não procura diminuir as consequências ou foge; doloso: aumento de 1/3 se a vítima é menor de 14 ou maior de 60 anos.","§5º: no culposo, perdão judicial se as consequências atingirem o próprio agente de modo grave.","§6º: aumento de 1/3 até a metade se praticado por milícia privada sob pretexto de segurança ou por grupo de extermínio."]'::jsonb, '["Homicídio qualificado É crime hediondo (regra da lei especial); privilegiado e qualificado podem coexistir se as qualificadoras forem objetivas (tema de doutrina e jurisprudência).","O privilégio é causa de DIMINUIÇÃO de pena (1/6 a 1/3), e o homicídio qualificado tem pena de 12 a 30 anos.","As causas do §4º se dividem: culposo (inobservância de regra técnica, omissão de socorro, fuga) e doloso (vítima menor de 14 ou maior de 60).","Confira no texto as redações recentes (leis de 2024 e 2026) dos incisos VII a X e dos parágrafos 2º-B a 2º-D."]'::jsonb, 'Matar alguém por motivo fútil, como uma discussão de trânsito banal, é homicídio qualificado (pena de 12 a 30 anos).', '["Assertiva que fixa a pena do homicídio simples em 12 a 30 anos confunde com a forma qualificada: o caput prevê reclusão de 6 a 20 anos.","Assertiva que dispensa a vítima ser maior de 60 anos para o aumento do §4º, parte final, erra: o aumento exige vítima menor de 14 ou maior de 60 anos no homicídio doloso."]'::jsonb, '[{"termo":"Dolo e culpa","significado":"No homicídio doloso o agente quer ou assume o risco do resultado; no culposo, dá causa por imprudência, negligência ou imperícia."},{"termo":"Meio insidioso","significado":"Meio disfarçado, que surpreende a vítima, como o veneno."}]'::jsonb, '["Art. 121-A (feminicídio)","Art. 18 (dolo e culpa)","Art. 61 (agravantes)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-121'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Feminicídio: matar mulher por razões da condição do sexo feminino, com reclusão de 20 a 40 anos. Há razões da condição do sexo feminino quando o crime envolve violência doméstica e familiar ou menosprezo ou discriminação à condição de mulher. A pena aumenta de 1/3 até a metade em situações como gestação ou até 3 meses após o parto, vítima mãe ou responsável por criança, adolescente ou pessoa com deficiência, vítima menor de 14, maior de 60 ou com deficiência ou doença degenerativa, presença física ou virtual de descendente ou ascendente, descumprimento de medidas protetivas e nas circunstâncias dos incisos III, IV e VIII do §2º do art. 121. As circunstâncias pessoais elementares do §1º comunicam-se ao coautor ou partícipe.', '["Caput: reclusão de 20 a 40 anos.","§1º: razões da condição do sexo feminino: I – violência doméstica e familiar; II – menosprezo ou discriminação à condição de mulher.","§2º: aumento de 1/3 até a metade em cinco hipóteses (gestação ou 3 meses pós-parto etc.; vulnerabilidades da vítima; presença de descendente ou ascendente; descumprimento de medidas protetivas; circunstâncias de III, IV e VIII do §2º do art. 121).","§3º: as circunstâncias pessoais elementares do §1º se comunicam ao coautor ou partícipe."]'::jsonb, '["O feminicídio agora é crime autônomo (art. 121-A), com pena de 20 a 40 anos.","A mulher deve ser vítima por razões da condição do sexo feminino (violência doméstica ou menosprezo/discriminação).","O aumento vai de 1/3 até a metade."]'::jsonb, 'Marido mata a esposa no contexto de violência doméstica e familiar: feminicídio (pena de 20 a 40 anos).', '["Assertiva que trata o feminicídio como qualificadora do art. 121 desatualiza a norma: hoje é o crime autônomo do art. 121-A."]'::jsonb, '[{"termo":"Razões da condição do sexo feminino","significado":"Violência doméstica e familiar, ou menosprezo ou discriminação à condição de mulher."}]'::jsonb, '["Art. 121","Art. 92, II"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-121-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Vicaricídio: matar descendente, ascendente, dependente, enteado ou pessoa sob guarda ou responsabilidade direta da mulher, com o fim específico de causar-lhe sofrimento, punição ou controle, no contexto de violência doméstica e familiar. Pena: reclusão de 20 a 40 anos, aumentada de 1/3 até a metade se praticado na presença da mulher visada, contra criança, adolescente, pessoa idosa ou com deficiência, ou em descumprimento de medida protetiva de urgência.', '["Matar parente, dependente ou pessoa sob guarda da mulher, para causar-lhe sofrimento, punição ou controle.","Contexto de violência doméstica e familiar.","Reclusão de 20 a 40 anos.","Aumento de 1/3 até a metade: na presença da mulher; contra criança, adolescente, idoso ou pessoa com deficiência; descumprimento de medida protetiva."]'::jsonb, '["Exige FIM ESPECÍFICO (sofrimento, punição ou controle da mulher).","A vítima direta é terceiro ligado à mulher, não a mulher."]'::jsonb, 'O agressor mata o filho da ex-companheira para fazê-la sofrer: vicaricídio.', '["Assertiva que dispensa o fim específico de causar sofrimento, punição ou controle contraria o caput."]'::jsonb, '[{"termo":"Vicaricídio","significado":"Nome dado ao crime de matar pessoa próxima à mulher para atingi-la."}]'::jsonb, '["Art. 121-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-121-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Induzimento, instigação ou auxílio a suicídio ou a automutilação: induzir ou instigar alguém a suicidar-se ou a praticar automutilação, ou prestar auxílio material para que o faça. Pena base: reclusão de 6 meses a 2 anos. Se resulta lesão grave ou gravíssima: reclusão de 1 a 3 anos; se o suicídio se consuma ou da automutilação resulta morte: reclusão de 2 a 6 anos. A pena é duplicada por motivo egoístico, torpe ou fútil ou se a vítima é menor ou tem diminuída a capacidade de resistência; aumentada até o dobro se por rede de computadores, rede social ou transmissão em tempo real; e em dobro se o autor é líder, coordenador ou administrador de grupo, comunidade ou rede virtual. Casos de menor de 14 anos ou sem discernimento remetem a lesão gravíssima ou homicídio.', '["Condutas: induzir, instigar ou auxiliar materialmente.","Caput: reclusão de 6 meses a 2 anos.","§1º: lesão grave ou gravíssima: 1 a 3 anos.","§2º: suicídio consumado ou morte pela automutilação: 2 a 6 anos.","§3º: pena duplicada por motivo egoístico, torpe ou fútil, ou vítima menor ou com resistência diminuída.","§4º: aumentada até o dobro por meio de rede de computadores, rede social ou transmissão em tempo real.","§5º: pena em dobro se o autor é líder, coordenador ou administrador de grupo ou rede virtual.","§6º e §7º: vítima menor de 14 anos ou sem discernimento: responde por lesão gravíssima (art. 129, §2º) ou homicídio (art. 121)."]'::jsonb, '["O crime só se consuma nas formas dos §§1º e 2º se houver resultado (lesão grave ou morte); o caput pune a conduta em si.","Confira os §§6º e 7º: contra menor de 14 anos ou sem discernimento, desloca-se para lesão gravíssima ou homicídio."]'::jsonb, 'O líder de um grupo em rede social instiga participantes ao suicídio: aplica-se a pena em dobro (§5º) e pode haver aumento pelo meio (§4º).', '["Assertiva que trata o induzimento ao suicídio como crime impunível se não há resultado erra: o caput pune a conduta."]'::jsonb, '[{"termo":"Automutilação","significado":"Lesão que a pessoa causa a si mesma."}]'::jsonb, '["Art. 121 (homicídio)","Art. 129 (lesão corporal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-122'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Infanticídio: matar, sob a influência do estado puerperal, o próprio filho, durante o parto ou logo após. O texto exibido traz apenas a descrição da conduta; a pena do infanticídio é de detenção (consulte o texto oficial completo).', '["Autora: a mãe, sob a influência do estado puerperal.","Vítima: o próprio filho, durante o parto ou logo após.","Tipo especial em relação ao homicídio (privilegiado em razão do estado puerperal)."]'::jsonb, '["Elementares: ESTADO PUERPERAL + durante o parto ou logo após.","Na doutrina, o estado puerperal e a qualidade de mãe são elementares, e por isso se comunicam ao coautor (art. 30)."]'::jsonb, 'Mãe, em estado puerperal, mata o recém-nascido logo após o parto: infanticídio, não homicídio.', '["Assertiva que aplica o infanticídio à morte do filho muito tempo depois do parto, sem relação com o estado puerperal, erra."]'::jsonb, '[{"termo":"Estado puerperal","significado":"Alteração física e psíquica da mulher durante e logo após o parto."}]'::jsonb, '["Art. 121","Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-123'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Autoaborto e aborto consentido: provocar aborto em si mesma ou consentir que outrem o provoque. O texto oficial traz a indicação ''Vide ADPF 54'': confira a decisão do STF sobre o tema.', '["Gestante que provoca aborto em si mesma.","Gestante que consente que outra pessoa lho provoque."]'::jsonb, '["É crime próprio: só a gestante pratica. O terceiro que provoca com consentimento responde pelo art. 126.","O texto remete à ADPF 54: antes de memorizar o alcance, confira o julgamento."]'::jsonb, 'A gestante toma substância abortiva por conta própria: art. 124.', '["Assertiva que aplica o art. 124 ao médico que realiza o aborto com consentimento da gestante erra: ele responde pelo art. 126."]'::jsonb, '[{"termo":"Crime próprio","significado":"Crime que só pode ser praticado por determinada pessoa (aqui, a gestante)."}]'::jsonb, '["Arts. 125 a 128"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-124'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aborto provocado por terceiro sem o consentimento da gestante. É a forma mais grave do aborto provocado por terceiro; a pena é de reclusão (confira o texto oficial).', '["Terceiro provoca aborto, sem consentimento da gestante."]'::jsonb, '["Diferença entre os arts. 125 e 126: ausência ou presença de consentimento da gestante."]'::jsonb, 'Alguém agride a gestante com o fim de provocar aborto, sem o seu consentimento: art. 125.', '["Assertiva que exige o consentimento da gestante para o art. 125 inverte o tipo: ele pressupõe a ausência de consentimento."]'::jsonb, '[]'::jsonb, '["Art. 124","Art. 126","Art. 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-125'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aborto provocado por terceiro com o consentimento da gestante. Aplica-se a pena do artigo anterior (aborto sem consentimento) se a gestante não é maior de 14 anos, é alienada ou débil mental, ou se o consentimento é obtido mediante fraude, grave ameaça ou violência. O texto oficial traz ''Vide ADPF 54''.', '["Terceiro provoca aborto com o consentimento da gestante.","Parágrafo único: consentimento irrelevante se a gestante não é maior de 14 anos, é alienada ou débil mental, ou o consentimento é viciado por fraude, grave ameaça ou violência: pena do art. 125."]'::jsonb, '["Consentimento inválido (menor de 14, alienada mental ou obtido por fraude/ameaça/violência) equipara-se à ausência de consentimento.","Confira a ADPF 54 indicada no texto."]'::jsonb, 'Quem realiza aborto em gestante de 13 anos, mesmo com seu consentimento, responde com a pena do art. 125.', '["Assertiva que valida o consentimento de gestante menor de 14 anos erra: o parágrafo único o desconsidera."]'::jsonb, '[]'::jsonb, '["Arts. 124, 125, 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-126'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Forma qualificada: as penas dos dois artigos anteriores são aumentadas de um terço se, em consequência do aborto ou dos meios empregados, a gestante sofre lesão corporal de natureza grave, e duplicadas se lhe sobrevém a morte.', '["Lesão grave na gestante: aumento de um terço.","Morte da gestante: pena duplicada.","Vale para os crimes dos arts. 125 e 126 (terceiro)."]'::jsonb, '["Aumenta 1/3 (lesão grave) ou duplica (morte)."]'::jsonb, 'Procedimento de aborto clandestino causa a morte da gestante: pena duplicada.', '["Assertiva que aplica o art. 127 ao autoaborto da gestante (art. 124) erra: refere-se aos arts. 125 e 126."]'::jsonb, '[]'::jsonb, '["Arts. 125 e 126"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-127'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aborto legal: não se pune o aborto praticado por médico se não há outro meio de salvar a vida da gestante (aborto necessário) ou se a gravidez resulta de estupro e o aborto é precedido de consentimento da gestante ou, quando incapaz, de seu representante legal (aborto sentimental). O texto traz as indicações ''Vide ADPF 54'' e ''Vide ADPF 1207 MC/DF'': confira as decisões do STF.', '["Só o MÉDICO pratica o aborto legal.","I – aborto necessário: não há outro meio de salvar a vida da gestante.","II – gravidez resultante de estupro, com consentimento da gestante (ou do representante legal, se incapaz)."]'::jsonb, '["No inciso I não se exige consentimento (nem autorização judicial); no II exige-se consentimento da gestante.","O art. 128 afasta a PUNIÇÃO (não é causa de justificação de qualquer pessoa: é para o médico).","Confira as ADPFs citadas no texto."]'::jsonb, 'Médico realiza aborto porque a gravidez coloca em risco a vida da gestante e não há outro meio de salvá-la: não se pune.', '["Assertiva que exige autorização judicial para o aborto necessário erra: o texto não a exige.","Assertiva que permite que enfermeira realize o aborto do art. 128 contraria o caput (aborto praticado por médico)."]'::jsonb, '[{"termo":"Aborto necessário","significado":"Aborto para salvar a vida da gestante."}]'::jsonb, '["Arts. 124 a 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-128'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lesão corporal: ofender a integridade corporal ou a saúde de outrem, com detenção de 3 meses a 1 ano (lesão leve). Lesão grave (§1º): incapacidade para as ocupações habituais por mais de 30 dias, perigo de vida, debilidade permanente de membro, sentido ou função, ou aceleração de parto: reclusão de 1 a 5 anos. Lesão gravíssima (§2º): incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, sentido ou função, deformidade permanente ou aborto: reclusão de 2 a 8 anos. Lesão seguida de morte (§3º): reclusão de 4 a 12 anos. Há ainda diminuição de pena (§4º), substituição por multa (§5º), forma culposa (§6º, detenção de 2 meses a 1 ano), aumentos (§§7º a 8º-A), violência doméstica (§9º, reclusão de 2 a 5 anos) e aumentos específicos (§§10 a 12).', '["Caput: detenção de 3 meses a 1 ano.","§1º: grave (incapacidade por mais de 30 dias; perigo de vida; debilidade permanente; aceleração de parto): reclusão de 1 a 5 anos.","§2º: gravíssima (incapacidade permanente; enfermidade incurável; perda ou inutilização; deformidade permanente; aborto): reclusão de 2 a 8 anos.","§3º: lesão seguida de morte, sem dolo quanto à morte: reclusão de 4 a 12 anos.","§4º: redução de um sexto a um terço (valor social ou moral, ou violenta emoção).","§5º: se as lesões não são graves, o juiz pode substituir a detenção por multa (nas hipóteses do §4º ou lesões recíprocas).","§6º: culposa: detenção de 2 meses a 1 ano.","§9º: violência doméstica (ascendente, descendente, irmão, cônjuge, companheiro, convivência, relações domésticas): reclusão de 2 a 5 anos.","§§10 a 12: aumentos de um terço (violência doméstica nos §§1º a 3º, vítima com deficiência) e de 1/3 a 2/3 contra agentes públicos listados e seus familiares."]'::jsonb, '["Grave: incapacidade por MAIS de 30 dias; gravíssima: incapacidade PERMANENTE para o trabalho.","A lesão seguida de morte (§3º) é preterdolosa: dolo na lesão, culpa na morte.","O §9º trata de violência doméstica e exige a relação descrita no texto atual."]'::jsonb, 'Uma agressão que deixa a vítima impossibilitada de suas atividades por 40 dias é lesão grave (§1º, I).', '["Assertiva que classifica a incapacidade por 20 dias como lesão grave erra: exige mais de 30 dias.","Assertiva que atribui à lesão seguida de morte pena de detenção erra: é reclusão de 4 a 12 anos."]'::jsonb, '[{"termo":"Preterdolo","significado":"Dolo no resultado inicial (lesão) e culpa no resultado mais grave (morte)."}]'::jsonb, '["Art. 121, §§4º e 5º","Art. 19 (agravação pelo resultado)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-129'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Perigo de contágio venéreo: expor alguém, por meio de relações sexuais ou qualquer ato libidinoso, a contágio de moléstia venérea de que sabe ou deve saber que está contaminado. Pena: detenção de 3 meses a 1 ano, ou multa. Se a intenção é transmitir a moléstia: reclusão de 1 a 4 anos e multa. Somente se procede mediante representação.', '["Expor a contágio por ato sexual ou libidinoso, sabendo ou devendo saber estar contaminado.","Caput: detenção de 3 meses a 1 ano, ou multa.","§1º: intenção de transmitir: reclusão de 1 a 4 anos e multa.","§2º: ação penal condicionada à representação."]'::jsonb, '["Ação penal pública CONDICIONADA à representação (§2º)."]'::jsonb, 'Pessoa que sabe estar contaminada pratica relação sexual sem informar o parceiro, expondo-o a contágio.', '["Assertiva que torna incondicionada a ação do art. 130 contraria o §2º."]'::jsonb, '[]'::jsonb, '["Art. 131"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-130'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Perigo de contágio de moléstia grave: praticar, com o fim de transmitir a outrem moléstia grave de que está contaminado, ato capaz de produzir o contágio. Pena: reclusão de 1 a 4 anos e multa.', '["Exige fim de transmitir moléstia grave.","Ato capaz de produzir o contágio.","Reclusão de 1 a 4 anos e multa."]'::jsonb, '["Exige DOLO ESPECÍFICO: fim de transmitir.","Se há transmissão e resultado mais grave, pode responder por lesão ou homicídio, conforme o caso."]'::jsonb, 'Quem sabe estar contaminado pratica ato com o fim de transmitir a doença grave a outra pessoa.', '["Assertiva que dispensa o fim de transmitir no art. 131 erra: ele é elementar do tipo."]'::jsonb, '[]'::jsonb, '["Art. 130"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-131'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Perigo para a vida ou saúde de outrem: expor a vida ou a saúde de outrem a perigo direto e iminente. Pena: detenção de 3 meses a 1 ano, se o fato não constitui crime mais grave (crime subsidiário). A pena aumenta de um sexto a um terço se a exposição decorre do transporte de pessoas para a prestação de serviços em estabelecimentos de qualquer natureza, em desacordo com as normas legais.', '["Perigo DIRETO e IMINENTE.","Detenção de 3 meses a 1 ano.","Subsidiário: só se não há crime mais grave.","Aumento de 1/6 a 1/3 no transporte de pessoas para prestar serviços em desacordo com as normas."]'::jsonb, '["Crime de perigo concreto (perigo direto e iminente).","Subsidiariedade expressa: ''se o fato não constitui crime mais grave''."]'::jsonb, 'Transportar trabalhadores em veículo inadequado, em desacordo com as normas, expondo-os a perigo: pena aumentada.', '["Assertiva que aplica o art. 132 mesmo havendo crime mais grave erra: o tipo é subsidiário."]'::jsonb, '[{"termo":"Crime subsidiário","significado":"Crime que só se aplica se o fato não constituir crime mais grave."}]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-132'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abandono de incapaz: abandonar pessoa que está sob seu cuidado, guarda, vigilância ou autoridade e que, por qualquer motivo, é incapaz de defender-se dos riscos do abandono. Pena: reclusão de 2 a 5 anos. Se resulta lesão grave: 3 a 7 anos; se resulta morte: 8 a 14 anos. As penas aumentam-se de um terço se o abandono ocorre em lugar ermo, se o agente é ascendente, descendente, cônjuge, irmão, tutor ou curador da vítima, ou se a vítima é maior de 60 anos.', '["Abandonar pessoa sob cuidado, guarda, vigilância ou autoridade, incapaz de se defender.","Caput: reclusão de 2 a 5 anos.","§1º: lesão grave: 3 a 7 anos.","§2º: morte: 8 a 14 anos.","§3º: aumento de 1/3 se lugar ermo; se o agente é ascendente, descendente, cônjuge, irmão, tutor ou curador; ou vítima maior de 60 anos."]'::jsonb, '["Penas e aumentos seguem a redação atual do texto (pena de 2 a 5 anos no caput).","Exige relação de cuidado, guarda, vigilância ou autoridade."]'::jsonb, 'Cuidador abandona idoso acamado em local isolado: abandono de incapaz, com aumento por lugar ermo e vítima idosa.', '["Assertiva que aplica o art. 133 a qualquer pessoa que encontre incapaz em perigo erra: exige a relação de cuidado, guarda, vigilância ou autoridade (para o simples encontro, veja a omissão de socorro, art. 135)."]'::jsonb, '[]'::jsonb, '["Art. 134","Art. 135"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-133'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exposição ou abandono de recém-nascido: expor ou abandonar recém-nascido para ocultar desonra própria. Pena: detenção de 6 meses a 2 anos. Se resulta lesão grave: detenção de 1 a 3 anos; se resulta morte: detenção de 2 a 6 anos.', '["Fim especial: ocultar desonra própria.","Caput: detenção de 6 meses a 2 anos.","§1º: lesão grave: 1 a 3 anos.","§2º: morte: 2 a 6 anos."]'::jsonb, '["Exige a finalidade de ocultar desonra PRÓPRIA.","As penas são de detenção."]'::jsonb, 'Mãe abandona o recém-nascido para esconder a gravidez: art. 134.', '["Assertiva que dispensa o fim de ocultar desonra própria erra: é elementar."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-134'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Omissão de socorro: deixar de prestar assistência, quando possível fazê-lo sem risco pessoal, à criança abandonada ou extraviada, ou à pessoa inválida ou ferida, ao desamparo ou em grave e iminente perigo; ou não pedir, nesses casos, o socorro da autoridade pública. Pena: detenção de 1 a 6 meses, ou multa. A pena é aumentada de metade se da omissão resulta lesão corporal grave, e triplicada se resulta a morte.', '["Deixar de prestar assistência, sem risco pessoal, à criança abandonada ou extraviada, pessoa inválida ou ferida, ao desamparo ou em grave e iminente perigo.","Ou não pedir o socorro da autoridade pública.","Pena: detenção de 1 a 6 meses, ou multa.","Aumento de metade (lesão grave) e triplicação (morte)."]'::jsonb, '["Só há omissão de socorro se for POSSÍVEL ajudar SEM RISCO PESSOAL.","Alternativas: prestar assistência OU pedir socorro à autoridade.","Aumento de metade na lesão grave; pena triplicada na morte."]'::jsonb, 'Motorista vê uma pessoa ferida na estrada, nada faz e nem chama o socorro: omissão de socorro.', '["Assertiva que exige que o omitente assuma risco pessoal para prestar socorro erra: o tipo ressalva o risco pessoal."]'::jsonb, '[]'::jsonb, '["Art. 13, §2º (omissão relevante)","Art. 135-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-135'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Condicionamento de atendimento médico-hospitalar emergencial: exigir cheque-caução, nota promissória ou qualquer garantia, bem como o preenchimento prévio de formulários administrativos, como condição para o atendimento médico-hospitalar emergencial. Pena: detenção de 3 meses a 1 ano e multa. A pena aumenta até o dobro se da negativa de atendimento resulta lesão grave, e até o triplo se resulta morte.', '["Exigir garantia ou formulário prévio como condição para atendimento de emergência.","Detenção de 3 meses a 1 ano e multa.","Aumento: até o dobro (lesão grave) e até o triplo (morte)."]'::jsonb, '["Protege o atendimento EMERGENCIAL.","Aumentos: até o dobro e até o triplo (diferente da omissão de socorro, que aumenta de metade e tripla)."]'::jsonb, 'O hospital exige cheque-caução antes de atender paciente em emergência: art. 135-A.', '["Assertiva que aplica o art. 135-A ao atendimento eletivo erra: trata de atendimento médico-hospitalar emergencial."]'::jsonb, '[]'::jsonb, '["Art. 135"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-135-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Maus-tratos: expor a perigo a vida ou a saúde de pessoa sob sua autoridade, guarda ou vigilância, para fim de educação, ensino, tratamento ou custódia, privando-a de alimentação ou cuidados indispensáveis, sujeitando-a a trabalho excessivo ou inadequado ou abusando de meios de correção ou disciplina. Pena: reclusão de 2 a 5 anos. Lesão grave: 3 a 7 anos; morte: 8 a 14 anos. Aumenta-se um terço se a vítima é menor de 14 anos.', '["Vítima sob autoridade, guarda ou vigilância, para educação, ensino, tratamento ou custódia.","Modos: privar de alimentação ou cuidados, trabalho excessivo ou inadequado, abuso de correção ou disciplina.","Caput: reclusão de 2 a 5 anos.","§1º: lesão grave: 3 a 7 anos. §2º: morte: 8 a 14 anos.","§3º: aumento de 1/3 se a vítima é menor de 14 anos."]'::jsonb, '["O fim deve ser educação, ensino, tratamento ou custódia (relação de autoridade, guarda ou vigilância).","O abuso dos meios de correção é conduta típica; o uso moderado não."]'::jsonb, 'Responsável priva de alimentação criança sob seus cuidados como castigo: maus-tratos.', '["Assertiva que aplica o art. 136 a qualquer pessoa sem relação de autoridade, guarda ou vigilância erra."]'::jsonb, '[]'::jsonb, '["Art. 133 (abandono de incapaz)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-136'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Rixa: participar de rixa, salvo para separar os contendores. Pena: detenção de 15 dias a 2 meses, ou multa. Se ocorre morte ou lesão corporal grave, aplica-se, pelo fato da participação na rixa, detenção de 6 meses a 2 anos.', '["Participar de rixa (briga generalizada), salvo para separar os contendores.","Pena: detenção de 15 dias a 2 meses, ou multa.","Parágrafo único: morte ou lesão grave: detenção de 6 meses a 2 anos, pela participação."]'::jsonb, '["Quem entra na rixa para separar os contendores não comete o crime.","A qualificadora do parágrafo único pune a PARTICIPAÇÃO, mesmo sem saber quem causou o resultado."]'::jsonb, 'Briga generalizada em que todos agridem todos e alguém morre: todos os rixosos respondem pelo parágrafo único.', '["Assertiva que pune quem intervém só para separar os contendores erra: o tipo ressalva essa hipótese."]'::jsonb, '[{"termo":"Rixa","significado":"Briga tumultuária entre três ou mais pessoas, com agressões recíprocas."}]'::jsonb, '["Art. 129 (lesão corporal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-137'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Calúnia: imputar falsamente a alguém fato definido como crime. Pena: detenção de 6 meses a 2 anos e multa. Na mesma pena incorre quem, sabendo falsa a imputação, a propala ou divulga. É punível a calúnia contra os mortos. Admite-se a prova da verdade (exceção da verdade), salvo se o fato imputado é crime de ação privada e o ofendido não foi condenado por sentença irrecorrível; se o fato é imputado a quem indica o inciso I do art. 141; ou se, do crime imputado, embora de ação pública, o ofendido foi absolvido por sentença irrecorrível.', '["Imputar falsamente fato definido COMO CRIME.","Pena: detenção de 6 meses a 2 anos e multa.","§1º: pune quem, sabendo falsa a imputação, a propala ou divulga.","§2º: calúnia contra os mortos é punível.","§3º: exceção da verdade admitida, salvo nos casos dos incisos I a III."]'::jsonb, '["Calúnia exige imputação FALSA de FATO DEFINIDO COMO CRIME (na difamação, o fato é só ofensivo à reputação).","Calúnia contra os mortos é punível (difamação e injúria contra mortos não)."]'::jsonb, 'Dizer falsamente, em público, que um vizinho furtou um carro é calúnia.', '["Assertiva que afirma que só a calúnia contra pessoa viva é punível erra: o §2º pune a calúnia contra os mortos."]'::jsonb, '[{"termo":"Exceção da verdade","significado":"Direito de provar que o fato imputado é verdadeiro."}]'::jsonb, '["Arts. 139 e 140","Art. 141"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-138'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Difamação: imputar a alguém fato ofensivo à sua reputação. Pena: detenção de 3 meses a 1 ano e multa. A exceção da verdade só se admite se o ofendido é funcionário público e a ofensa é relativa ao exercício de suas funções.', '["Imputar fato (verdadeiro ou falso) ofensivo à reputação.","Pena: detenção de 3 meses a 1 ano e multa.","Exceção da verdade só se o ofendido é funcionário público e a ofensa se refere ao exercício das funções."]'::jsonb, '["Na difamação, o fato não precisa ser crime; basta ofender a REPUTAÇÃO (honra objetiva).","A exceção da verdade é restrita (funcionário público no exercício da função)."]'::jsonb, 'Espalhar que um comerciante deu calote em fornecedores (fato ofensivo à reputação) é difamação.', '["Assertiva que admite a exceção da verdade na difamação contra qualquer pessoa erra: só contra funcionário público em razão das funções."]'::jsonb, '[{"termo":"Honra objetiva","significado":"Reputação: o que os outros pensam da pessoa."}]'::jsonb, '["Arts. 138 e 140"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-139'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Injúria: ofender a dignidade ou o decoro de alguém (honra subjetiva). Pena: detenção de 1 a 6 meses, ou multa. O juiz pode deixar de aplicar a pena se o ofendido, de forma reprovável, provocou diretamente a injúria, ou em caso de retorsão imediata que consista em outra injúria. Injúria real (violência ou vias de fato aviltantes): detenção de 3 meses a 1 ano e multa, além da pena da violência. Injúria com elementos referentes a religião ou à condição de pessoa idosa ou com deficiência: reclusão de 1 a 3 anos e multa.', '["Ofender a dignidade ou o decoro.","Caput: detenção de 1 a 6 meses, ou multa.","§1º: perdão judicial se houver provocação reprovável do ofendido ou retorsão imediata.","§2º: injúria real: detenção de 3 meses a 1 ano e multa, mais a pena da violência.","§3º: injúria qualificada por elementos de religião, idade (idoso) ou deficiência: reclusão de 1 a 3 anos e multa."]'::jsonb, '["Injúria atinge a honra SUBJETIVA (dignidade e decoro).","Retorsão imediata e provocação reprovável autorizam o perdão judicial (§1º).","O §3º refere-se a religião, pessoa idosa ou com deficiência no texto atual; outras formas de discriminação têm lei específica."]'::jsonb, 'Chamar alguém, na sua frente, de adjetivo humilhante: injúria.', '["Assertiva que exige imputação de fato determinado na injúria erra: a injúria atribui qualidade ofensiva, sem fato determinado."]'::jsonb, '[{"termo":"Honra subjetiva","significado":"Sentimento que a pessoa tem sobre si mesma (dignidade e decoro)."}]'::jsonb, '["Arts. 138, 139, 141, 145"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-140'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Disposições comuns aos crimes contra a honra: as penas aumentam-se de um terço se qualquer dos crimes é cometido contra o Presidente da República ou chefe de governo estrangeiro; contra funcionário público em razão de suas funções ou contra os Presidentes do Senado, da Câmara ou do STF; na presença de várias pessoas ou por meio que facilite a divulgação; ou contra criança, adolescente, pessoa maior de 60 anos ou com deficiência (exceto a hipótese do art. 140, §3º). Se o crime é cometido mediante paga ou promessa de recompensa, a pena é em dobro. Se cometido ou divulgado em redes sociais, aplica-se em triplo a pena. Se contra a mulher por razões da condição do sexo feminino (art. 121-A, §1º), a pena é em dobro.', '["Aumento de 1/3: Presidente da República ou chefe de governo estrangeiro; funcionário público em razão de suas funções, ou Presidentes do Senado, da Câmara e do STF; presença de várias pessoas ou meio de divulgação; criança, adolescente, maior de 60 anos ou pessoa com deficiência.","§1º: paga ou promessa de recompensa: em dobro.","§2º: redes sociais: em triplo.","§3º: mulher por razões da condição do sexo feminino: em dobro."]'::jsonb, '["Aumento de 1/3 no caput; em dobro (paga, violência de gênero); em TRIPLO (redes sociais).","O inciso IV exclui a hipótese da injúria qualificada do art. 140, §3º."]'::jsonb, 'Calúnia divulgada em rede social tem a pena aplicada em triplo (§2º).', '["Assertiva que aplica o aumento em dobro, e não em triplo, aos crimes contra a honra praticados em redes sociais contraria o §2º."]'::jsonb, '[]'::jsonb, '["Arts. 138 a 140","Art. 145"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-141'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exclusão do crime: não constituem injúria ou difamação punível a ofensa irrogada em juízo, na discussão da causa, pela parte ou por seu procurador; a opinião desfavorável da crítica literária, artística ou científica, salvo quando inequívoca a intenção de injuriar ou difamar; e o conceito desfavorável emitido por funcionário público, em apreciação ou informação que preste no cumprimento de dever do ofício. Nos casos dos incisos I e III, responde pela injúria ou difamação quem lhe dá publicidade.', '["I – ofensa em juízo, na discussão da causa, pela parte ou seu procurador.","II – opinião desfavorável da crítica literária, artística ou científica, salvo inequívoca intenção de ofender.","III – conceito desfavorável de funcionário público no cumprimento do dever do ofício.","Parágrafo único: quem dá publicidade nos casos I e III responde."]'::jsonb, '["Vale para INJÚRIA e DIFAMAÇÃO; a calúnia não está contemplada.","Quem dá PUBLICIDADE às ofensas dos incisos I e III responde."]'::jsonb, 'Advogado, na petição, usa expressões duras contra a parte adversa, dentro da discussão da causa: não há crime punível.', '["Assertiva que estende a imunidade do art. 142 à calúnia erra: refere-se à injúria e à difamação."]'::jsonb, '[]'::jsonb, '["Arts. 139 e 140"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-142'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Retratação: o querelado que, antes da sentença, se retrata cabalmente da calúnia ou da difamação fica isento de pena. Se usou meios de comunicação, a retratação far-se-á, se o ofendido quiser, pelos mesmos meios.', '["Retratação cabal antes da sentença: isenção de pena.","Cabe na calúnia e na difamação (não na injúria).","Meios de comunicação: retratação pelos mesmos meios, se o ofendido desejar."]'::jsonb, '["A retratação NÃO vale para a injúria."]'::jsonb, 'O ofensor publica retratação completa antes da sentença: fica isento de pena na calúnia.', '["Assertiva que admite retratação na injúria erra: o art. 143 trata de calúnia e difamação."]'::jsonb, '[{"termo":"Retratação","significado":"Desdizer-se, retirando a ofensa de forma completa."}]'::jsonb, '["Art. 107, VI"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-143'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pedido de explicações em juízo: se de referências, alusões ou frases se infere calúnia, difamação ou injúria, quem se julga ofendido pode pedir explicações em juízo. Aquele que se recusa a dá-las ou, a critério do juiz, não as dá satisfatórias, responde pela ofensa.', '["Procedimento para ofensas veladas (referências, alusões ou frases).","Quem se recusa a explicar ou não dá explicações satisfatórias responde pela ofensa."]'::jsonb, '["É procedimento preparatório, útil quando a ofensa é equívoca."]'::jsonb, 'Alguém faz insinuações veladas sobre um colega: este pede explicações em juízo antes de processar.', '["Assertiva que dispensa o pedido de explicações para toda calúnia, difamação ou injúria erra: ele é cabível quando a ofensa se infere de referências, alusões ou frases."]'::jsonb, '[]'::jsonb, '["Arts. 138 a 140"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-144'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ação penal nos crimes contra a honra: em regra somente se procede mediante queixa (ação penal privada), salvo quando, no caso do art. 140, §2º, da violência resulta lesão corporal. Procede-se mediante requisição do Ministro da Justiça no caso do art. 141, I (Presidente da República ou chefe de governo estrangeiro), e mediante representação do ofendido no caso do art. 141, II (funcionário público em razão das funções etc.) e no caso do art. 140, §3º.', '["Regra: queixa (ação privada).","Exceção: injúria real com lesão corporal: ação pública.","Parágrafo único: requisição do Ministro da Justiça (art. 141, I); representação (art. 141, II e art. 140, §3º)."]'::jsonb, '["Regra: ação PRIVADA; exceções: pública condicionada à requisição ou à representação."]'::jsonb, 'Calúnia contra o Presidente da República: ação pública condicionada à requisição do Ministro da Justiça.', '["Assertiva que torna pública incondicionada a ação nos crimes contra a honra, em regra, erra: a regra é queixa."]'::jsonb, '[]'::jsonb, '["Arts. 138 a 141"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-145'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constrangimento ilegal: constranger alguém, mediante violência ou grave ameaça, ou depois de lhe haver reduzido, por qualquer outro meio, a capacidade de resistência, a não fazer o que a lei permite ou a fazer o que ela não manda. Pena: detenção de 3 meses a 1 ano, ou multa. As penas aplicam-se cumulativamente e em dobro quando se reúnem mais de três pessoas ou há emprego de armas; aplicam-se também as da violência. Não se compreendem a intervenção médica ou cirúrgica sem consentimento justificada por iminente perigo de vida, nem a coação para impedir suicídio.', '["Constranger mediante violência, grave ameaça ou redução da capacidade de resistência.","Pena: detenção de 3 meses a 1 ano, ou multa.","§1º: mais de 3 pessoas ou arma: penas cumulativas e em dobro.","§2º: aplicam-se também as penas da violência.","§3º: não é constrangimento ilegal a intervenção médica por iminente perigo de vida, nem a coação para impedir suicídio."]'::jsonb, '["Mais de TRÊS pessoas (ou emprego de armas) = pena cumulativa e em dobro.","O crime é subsidiário em relação a crimes mais graves (como roubo e extorsão)."]'::jsonb, 'O agente força alguém, com ameaça de agressão, a assinar um documento sem proveito econômico: constrangimento ilegal.', '["Assertiva que considera crime a coação exercida para impedir suicídio erra: o §3º, II, a exclui."]'::jsonb, '[]'::jsonb, '["Art. 146-A","Art. 158 (extorsão)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-146'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Intimidação sistemática (bullying): intimidar sistematicamente, individualmente ou em grupo, mediante violência física ou psicológica, uma ou mais pessoas, de modo intencional e repetitivo, sem motivação evidente, por atos de intimidação, humilhação ou discriminação ou ações verbais, morais, sexuais, sociais, psicológicas, físicas, materiais ou virtuais. Pena: multa, se a conduta não constituir crime mais grave. Se realizada por meio da rede de computadores, rede social, aplicativos, jogos on-line ou qualquer meio digital, ou transmitida em tempo real (cyberbullying): reclusão de 2 a 4 anos e multa, se não constituir crime mais grave.', '["Intimidação sistemática: intencional, repetitiva e sem motivação evidente.","Caput: multa, se não houver crime mais grave.","Parágrafo único (cyberbullying): reclusão de 2 a 4 anos e multa, se não houver crime mais grave."]'::jsonb, '["Crime SUBSIDIÁRIO: só se não houver crime mais grave.","A forma virtual (cyberbullying) tem pena de reclusão de 2 a 4 anos."]'::jsonb, 'Grupo de alunos humilha repetidamente um colega por redes sociais: cyberbullying.', '["Assertiva que fixa pena de reclusão para o bullying presencial (caput) erra: a pena do caput é multa."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-146-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ameaça: ameaçar alguém, por palavra, escrito ou gesto, ou qualquer outro meio simbólico, de causar-lhe mal injusto e grave. Pena: detenção de 1 a 6 meses, ou multa. Se contra a mulher por razões da condição do sexo feminino, pena em dobro. Somente se procede mediante representação, exceto na hipótese de ameaça contra a mulher por razões da condição do sexo feminino.', '["Mal injusto e grave por palavra, escrito, gesto ou meio simbólico.","Pena: detenção de 1 a 6 meses, ou multa.","§1º: mulher por razões da condição do sexo feminino: em dobro.","§2º: ação condicionada à representação, exceto no §1º (incondicionada)."]'::jsonb, '["Regra: ação condicionada à representação; ameaça contra a mulher por razões do sexo feminino: ação pública incondicionada."]'::jsonb, 'Ameaçar de morte o ex-companheiro por mensagem: ameaça.', '["Assertiva que exige representação da ofendida na ameaça contra a mulher por razões da condição do sexo feminino erra: nesse caso a ação é incondicionada."]'::jsonb, '[]'::jsonb, '["Art. 147-A","Art. 147-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-147'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Perseguição (stalking): perseguir alguém, reiteradamente e por qualquer meio, ameaçando-lhe a integridade física ou psicológica, restringindo-lhe a capacidade de locomoção ou, de qualquer forma, invadindo ou perturbando sua esfera de liberdade ou privacidade. Pena: reclusão de 6 meses a 2 anos e multa. A pena aumenta de metade se contra criança, adolescente ou idoso, contra mulher por razões da condição de sexo feminino ou mediante concurso de 2 ou mais pessoas ou emprego de arma. As penas se aplicam sem prejuízo das da violência. Somente se procede mediante representação.', '["Conduta REITERADA, por qualquer meio.","Pena: reclusão de 6 meses a 2 anos e multa.","§1º: aumento de metade (criança, adolescente, idoso; mulher por razões do sexo feminino; concurso de 2 ou mais pessoas ou arma).","§2º: sem prejuízo das penas da violência.","§3º: ação condicionada à representação."]'::jsonb, '["Exige REITERAÇÃO.","Ação penal condicionada à representação."]'::jsonb, 'Alguém acompanha, liga e aparece repetidamente no local de trabalho da ex-namorada, perturbando sua privacidade: perseguição.', '["Assertiva que configura a perseguição com uma única conduta isolada erra: exige reiteração."]'::jsonb, '[{"termo":"Stalking","significado":"Perseguição reiterada que invade a esfera de liberdade ou privacidade da vítima."}]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-147-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violência psicológica contra a mulher: causar dano emocional à mulher que a prejudique e perturbe seu pleno desenvolvimento ou vise a degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, chantagem, ridicularização, limitação do direito de ir e vir ou qualquer outro meio que cause prejuízo à sua saúde psicológica e autodeterminação. Pena: reclusão de 6 meses a 2 anos e multa, se a conduta não constitui crime mais grave. A pena é aumentada de metade se cometido com uso de inteligência artificial ou outro recurso tecnológico que altere imagem ou som da vítima.', '["Dano emocional que prejudique, degrade ou controle a mulher.","Meios: ameaça, constrangimento, humilhação, manipulação, isolamento, chantagem, ridicularização, limitação do direito de ir e vir etc.","Pena: reclusão de 6 meses a 2 anos e multa, se não houver crime mais grave.","Aumento de metade se usar inteligência artificial ou recurso tecnológico que altere imagem ou som da vítima."]'::jsonb, '["Crime subsidiário (só se não houver crime mais grave).","A pena aumenta de metade quando há alteração de imagem ou som por meio tecnológico (por exemplo, deepfake)."]'::jsonb, 'Isolar a companheira de amigos e familiares e humilhá-la sistematicamente para controlá-la: violência psicológica.', '["Assertiva que exige lesão física para configurar o art. 147-B erra: o tipo trata de dano emocional."]'::jsonb, '[]'::jsonb, '["Art. 147-A","Lei Maria da Penha"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-147-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ameaça qualificada pelo contexto do crime organizado: ameaçar alguém, por palavra, escrito, gesto ou qualquer outro meio simbólico, de causar-lhe mal injusto e grave, no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil. Pena: reclusão de 1 a 3 anos.', '["Ameaça de mal injusto e grave.","No contexto da atuação ou para a consecução das condutas do art. 2º da lei do marco legal do combate ao crime organizado.","Pena: reclusão de 1 a 3 anos."]'::jsonb, '["A diferença para o art. 147 é o CONTEXTO (crime organizado), que eleva a pena."]'::jsonb, 'Integrante de organização criminosa ameaça uma testemunha para forçar o silêncio dela: art. 147-C.', '["Assertiva que aplica o art. 147-C a toda ameaça, independentemente do contexto, erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-147-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sequestro e cárcere privado: privar alguém de sua liberdade, mediante sequestro ou cárcere privado. Pena: reclusão de 1 a 3 anos. Forma qualificada (reclusão de 2 a 5 anos): vítima ascendente, descendente, cônjuge ou companheiro do agente ou maior de 60 anos; internação em casa de saúde ou hospital; privação por mais de 15 dias; vítima menor de 18 anos; fins libidinosos. Se resulta grave sofrimento físico ou moral por maus-tratos ou natureza da detenção: reclusão de 2 a 8 anos. Se cometido por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia: reclusão de 12 a 20 anos.', '["Caput: reclusão de 1 a 3 anos.","§1º: reclusão de 2 a 5 anos em cinco hipóteses (parente ou idoso; internação em casa de saúde ou hospital; mais de 15 dias; menor de 18 anos; fins libidinosos).","§2º: grave sofrimento físico ou moral: reclusão de 2 a 8 anos.","§3º: organização ultraviolenta, paramilitar ou milícia: reclusão de 12 a 20 anos (texto atual)."]'::jsonb, '["Mais de 15 dias de privação: qualificadora do §1º, III.","Vítima menor de 18 anos e fins libidinosos também qualificam."]'::jsonb, 'Manter alguém trancado por 20 dias: sequestro qualificado (reclusão de 2 a 5 anos).', '["Assertiva que fixa em 10 dias a duração para qualificar o sequestro erra: são mais de 15 dias."]'::jsonb, '[{"termo":"Cárcere privado","significado":"Privação da liberdade mantendo a vítima confinada em local fechado."}]'::jsonb, '["Art. 159 (extorsão mediante sequestro)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-148'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Redução a condição análoga à de escravo: submeter alguém a trabalhos forçados ou a jornada exaustiva, sujeitá-lo a condições degradantes de trabalho ou restringir, por qualquer meio, sua locomoção em razão de dívida contraída com o empregador ou preposto. Pena: reclusão de 2 a 8 anos e multa, além da pena correspondente à violência. Nas mesmas penas incorre quem cerceia o uso de meio de transporte do trabalhador para retê-lo, ou mantém vigilância ostensiva ou se apodera de documentos ou objetos pessoais para retê-lo. A pena aumenta de metade se contra criança ou adolescente ou por preconceito de raça, cor, etnia, religião ou origem.', '["Trabalhos forçados; jornada exaustiva; condições degradantes; restrição de locomoção por dívida.","Pena: reclusão de 2 a 8 anos, multa e pena da violência.","§1º: cerceio de transporte; vigilância ostensiva ou apoderamento de documentos ou objetos para reter o trabalhador.","§2º: aumento de metade (criança ou adolescente; preconceito de raça, cor, etnia, religião ou origem)."]'::jsonb, '["As QUATRO formas do caput são alternativas: basta uma para configurar o crime.","O crime protege a liberdade e a dignidade do trabalhador."]'::jsonb, 'Empregador retém os documentos dos trabalhadores e os obriga a pagar dívida de alojamento, impedindo sua saída: art. 149.', '["Assertiva que exige cumulativamente as quatro condutas para configurar o crime erra: são alternativas."]'::jsonb, '[]'::jsonb, '["Art. 149-A (tráfico de pessoas)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-149'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tráfico de pessoas: agenciar, aliciar, recrutar, transportar, transferir, comprar, alojar ou acolher pessoa, mediante grave ameaça, violência, coação, fraude ou abuso, com a finalidade de remover-lhe órgãos, tecidos ou partes do corpo; submetê-la a trabalho em condições análogas à de escravo ou a qualquer tipo de servidão; adoção ilegal; ou exploração sexual. Pena: reclusão de 4 a 8 anos e multa. A pena é aumentada de um terço até a metade se o crime é cometido por funcionário público no exercício das funções ou a pretexto de exercê-las, contra criança, adolescente, idoso ou pessoa com deficiência, entre outras hipóteses do texto completo.', '["Condutas: agenciar, aliciar, recrutar, transportar, transferir, comprar, alojar ou acolher.","Meios: grave ameaça, violência, coação, fraude ou abuso.","Finalidades: remoção de órgãos; trabalho escravo; servidão; adoção ilegal; exploração sexual.","Pena: reclusão de 4 a 8 anos e multa.","§1º: aumento de 1/3 até a metade (funcionário público; criança, adolescente, idoso ou pessoa com deficiência; relações de parentesco, domésticas e outras, conforme o texto completo)."]'::jsonb, '["São CINCO finalidades possíveis; basta uma.","Aumento de um terço até a metade (confira as demais hipóteses no texto completo)."]'::jsonb, 'Aliciar mulheres com falsas promessas de emprego no exterior para exploração sexual: tráfico de pessoas.', '["Assertiva que exige remoção de órgãos como finalidade única do tráfico de pessoas erra: há cinco finalidades."]'::jsonb, '[]'::jsonb, '["Art. 149","Lei de tráfico de pessoas"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-149-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violação de domicílio: entrar ou permanecer, clandestina ou astuciosamente, ou contra a vontade expressa ou tácita de quem de direito, em casa alheia ou em suas dependências. Pena: detenção de 1 a 3 meses, ou multa. Se cometido de noite, em lugar ermo, com violência ou arma, ou por duas ou mais pessoas: detenção de 6 meses a 2 anos, além da pena da violência. Não é crime a entrada durante o dia, com as formalidades legais, para efetuar prisão ou outra diligência, nem a entrada a qualquer hora quando algum crime está sendo ali praticado ou na iminência de o ser. O conceito de ''casa'' abrange compartimento habitado, aposento ocupado de habitação coletiva e compartimento não aberto ao público onde se exerce profissão ou atividade; não abrange hospedaria enquanto aberta, taverna e casa de jogo.', '["Entrar ou permanecer, clandestina ou astuciosamente, ou contra vontade expressa ou tácita.","Caput: detenção de 1 a 3 meses, ou multa.","§1º: noite, lugar ermo, violência ou arma, ou duas ou mais pessoas: detenção de 6 meses a 2 anos.","§3º: não é crime entrada durante o dia com formalidades legais para prisão ou diligência; ou a qualquer hora se há crime em andamento ou iminente.","§4º: ''casa'' = compartimento habitado; aposento de habitação coletiva; compartimento não aberto ao público para profissão ou atividade.","§5º: não é ''casa'' hospedaria aberta, taverna, casa de jogo."]'::jsonb, '["Entrada para prisão ou diligência: durante o DIA, com formalidades legais (à noite, só com consentimento ou em caso de crime em curso/iminente, desastre ou para prestar socorro, conforme a Constituição).","O §2º foi revogado."]'::jsonb, 'Policial entra, durante o dia, em uma casa munido de mandado judicial: não há crime (§3º, I).', '["Assertiva que considera crime a entrada em casa alheia quando um crime está sendo praticado ali erra: o §3º, II, a exclui."]'::jsonb, '[]'::jsonb, '["Art. 23 (excludentes de ilicitude)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-150'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violação de correspondência: devassar indevidamente o conteúdo de correspondência fechada, dirigida a outrem. Pena: detenção de 1 a 6 meses, ou multa. Na mesma pena incorre quem se apossa indevidamente de correspondência alheia, embora não fechada, e a sonega ou destrói (sonegação ou destruição de correspondência); quem divulga, transmite ou utiliza abusivamente comunicação telegráfica ou radioelétrica dirigida a terceiro, ou conversação telefônica entre outras pessoas; quem impede essa comunicação; e quem instala ou utiliza estação ou aparelho radioelétrico sem observância de disposição legal. As penas aumentam-se de metade se há dano para outrem. Com abuso de função em serviço postal, telegráfico, radioelétrico ou telefônico: detenção de 1 a 3 anos. Em regra, ação condicionada à representação, salvo nos casos do §1º, IV, e do §3º.', '["Caput: devassar correspondência fechada alheia: detenção de 1 a 6 meses, ou multa.","§1º, I: sonegação ou destruição de correspondência.","§1º, II e III: violação ou impedimento de comunicação telegráfica, radioelétrica ou telefônica.","§1º, IV: instalar ou usar estação radioelétrica sem observância legal.","§2º: aumento de metade se há dano a outrem.","§3º: abuso de função em serviço postal ou de telecomunicações: detenção de 1 a 3 anos.","§4º: representação, salvo §1º, IV, e §3º."]'::jsonb, '["Devassar exige correspondência FECHADA; a sonegação ou destruição alcança a correspondência mesmo aberta."]'::jsonb, 'Abrir carta fechada dirigida ao vizinho e ler o conteúdo: art. 151.', '["Assertiva que torna condicionada à representação a ação no abuso de função em serviço postal erra: o §4º a exclui."]'::jsonb, '[]'::jsonb, '["Art. 152","Art. 153"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-151'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Correspondência comercial: abusar da condição de sócio ou empregado de estabelecimento comercial ou industrial para, no todo ou em parte, desviar, sonegar, subtrair ou suprimir correspondência, ou revelar a estranho seu conteúdo. Pena: detenção de 3 meses a 2 anos. Somente se procede mediante representação.', '["Autor: sócio ou empregado de estabelecimento comercial ou industrial.","Condutas: desviar, sonegar, subtrair, suprimir correspondência ou revelar seu conteúdo a estranho.","Pena: detenção de 3 meses a 2 anos.","Ação condicionada à representação."]'::jsonb, '["Crime próprio: exige a qualidade de sócio ou empregado."]'::jsonb, 'Empregado de uma empresa sonega cartas comerciais da empresa e as revela a um concorrente.', '["Assertiva que torna incondicionada a ação do art. 152 contraria o parágrafo único."]'::jsonb, '[]'::jsonb, '["Art. 151"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-152'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Divulgação de segredo: divulgar alguém, sem justa causa, conteúdo de documento particular ou de correspondência confidencial, de que é destinatário ou detentor, e cuja divulgação possa produzir dano a outrem. Pena: detenção de 1 a 6 meses, ou multa. Ação condicionada à representação. O §1º-A pune a divulgação, sem justa causa, de informações sigilosas ou reservadas, assim definidas em lei, contidas ou não nos sistemas de informações ou bancos de dados da Administração Pública: detenção de 1 a 4 anos e multa. Quando resultar prejuízo para a Administração Pública, a ação penal será incondicionada.', '["Caput: divulgação sem justa causa de documento particular ou correspondência confidencial, com potencial de dano.","§1º: representação.","§1º-A: informações sigilosas ou reservadas da Administração: detenção de 1 a 4 anos e multa.","§2º: prejuízo à Administração Pública: ação incondicionada."]'::jsonb, '["A divulgação deve poder produzir DANO a outrem.","Informações sigilosas da Administração: pena maior (1 a 4 anos)."]'::jsonb, 'O destinatário divulga carta confidencial recebida, causando dano ao remetente, sem justa causa.', '["Assertiva que torna sempre condicionada à representação a ação do art. 153 erra: se há prejuízo à Administração Pública, é incondicionada (§2º)."]'::jsonb, '[]'::jsonb, '["Art. 154"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-153'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violação do segredo profissional: revelar alguém, sem justa causa, segredo de que tem ciência em razão de função, ministério, ofício ou profissão, e cuja revelação possa produzir dano a outrem. Pena: detenção de 3 meses a 1 ano, ou multa. Somente se procede mediante representação.', '["Segredo conhecido em razão de função, ministério, ofício ou profissão.","Revelação sem justa causa, com potencial de dano.","Pena: detenção de 3 meses a 1 ano, ou multa.","Ação condicionada à representação."]'::jsonb, '["A ''justa causa'' afasta o crime (ex.: dever legal de comunicar)."]'::jsonb, 'Advogado revela, sem justa causa, segredo do cliente, causando-lhe dano: art. 154.', '["Assertiva que pune a revelação do segredo mesmo com justa causa erra: o tipo exige ''sem justa causa''."]'::jsonb, '[]'::jsonb, '["Art. 153"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-154'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Invasão de dispositivo informático: invadir dispositivo informático de uso alheio, conectado ou não à rede, com o fim de obter, adulterar ou destruir dados ou informações sem autorização expressa ou tácita do usuário, ou de instalar vulnerabilidades para obter vantagem ilícita. Pena: reclusão de 1 a 4 anos e multa. Na mesma pena quem produz, oferece, distribui, vende ou difunde dispositivo ou programa com o intuito de permitir a conduta. Aumenta-se de 1/3 a 2/3 se resulta prejuízo econômico. Se resulta obtenção de conteúdo de comunicações eletrônicas privadas, segredos comerciais ou industriais, informações sigilosas ou controle remoto não autorizado: reclusão de 2 a 5 anos e multa, com aumento de um a dois terços se houver divulgação, comercialização ou transmissão a terceiro (confira o texto completo).', '["Invadir dispositivo de uso alheio, conectado ou não à rede, com o fim de obter, adulterar ou destruir dados ou instalar vulnerabilidades.","Caput: reclusão de 1 a 4 anos e multa.","§1º: produzir, oferecer, distribuir, vender ou difundir programa ou dispositivo para a prática.","§2º: prejuízo econômico: aumento de 1/3 a 2/3.","§3º: obtenção de comunicações privadas, segredos ou controle remoto: reclusão de 2 a 5 anos e multa."]'::jsonb, '["Vale mesmo que o dispositivo NÃO esteja conectado à rede.","Exige o fim específico (obter, adulterar ou destruir dados ou instalar vulnerabilidades)."]'::jsonb, 'Alguém invade o celular da ex-companheira para copiar conversas privadas: invasão de dispositivo informático (pode incidir o §3º).', '["Assertiva que exige que o dispositivo esteja conectado à internet erra: o tipo vale para dispositivo conectado ou não à rede."]'::jsonb, '[{"termo":"Dispositivo informático","significado":"Computador, celular, tablet e equipamentos semelhantes que armazenam ou processam dados."}]'::jsonb, '["Art. 154-B (ação penal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-154-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ação penal na invasão de dispositivo informático: nos crimes do art. 154-A somente se procede mediante representação, salvo se o crime é cometido contra a administração pública direta ou indireta de qualquer dos Poderes da União, Estados, Distrito Federal ou Municípios, ou contra empresas concessionárias de serviços públicos.', '["Regra: ação pública condicionada à representação.","Exceção: crime contra a administração pública direta ou indireta, ou contra concessionárias de serviços públicos: incondicionada."]'::jsonb, '["Regra: representação; contra a Administração ou concessionárias: ação pública incondicionada."]'::jsonb, 'Invasão do sistema de um órgão municipal: ação pública incondicionada.', '["Assertiva que exige representação mesmo na invasão de dispositivo de órgão da administração direta erra: nesse caso a ação é incondicionada."]'::jsonb, '[]'::jsonb, '["Art. 154-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-154-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Furto: subtrair, para si ou para outrem, coisa alheia móvel. Pena: reclusão de 1 a 6 anos e multa (texto atual). Aumento de metade se praticado durante o repouso noturno. Furto privilegiado (§2º): se o criminoso é primário e a coisa é de pequeno valor, o juiz pode substituir reclusão por detenção, diminuir de um a dois terços ou aplicar só multa. Energia elétrica e outras com valor econômico equiparam-se a coisa móvel (§3º). Furto qualificado (§4º, reclusão de 2 a 8 anos e multa): destruição ou rompimento de obstáculo; abuso de confiança, fraude, escalada ou destreza; chave falsa; concurso de duas ou mais pessoas; bens que comprometam o funcionamento de órgãos públicos ou serviços essenciais. Há ainda formas com pena de 4 a 10 anos (explosivo, fraude eletrônica, veículo levado a outro Estado ou ao exterior, animais, celulares e computadores, armas etc.) e causas de aumento para fraude eletrônica (servidor no exterior; idoso ou vulnerável). Confira o texto completo.', '["Caput: subtrair coisa alheia móvel; reclusão de 1 a 6 anos e multa.","§1º: aumento de metade no repouso noturno.","§2º: furto privilegiado (primário + pequeno valor).","§3º: equipara-se à coisa móvel a energia elétrica ou outra com valor econômico.","§4º: qualificadoras (obstáculo; confiança, fraude, escalada ou destreza; chave falsa; concurso de pessoas; bens essenciais): reclusão de 2 a 8 anos e multa.","§4º-A e seguintes: formas específicas com pena de 4 a 10 anos (explosivo, fraude por dispositivo eletrônico, veículo para outro Estado ou exterior, semovente ou animal doméstico, celular e computador, arma de fogo, substâncias explosivas)."]'::jsonb, '["Repouso noturno é causa de AUMENTO (metade) no furto simples; privilégio exige primariedade e coisa de pequeno valor.","Qualificadoras do §4º: reclusão de 2 a 8 anos.","As penas e hipóteses seguem a redação atual do texto (leis de 2018, 2021 e 2026)."]'::jsonb, 'Subtrair um celular de dentro de uma bolsa, sem violência: furto (e, conforme o texto atual, forma com pena de 4 a 10 anos se for celular).', '["Assertiva que confunde furto com roubo por exigir violência ou grave ameaça no furto erra: o furto é sem violência."]'::jsonb, '[{"termo":"Subtrair","significado":"Retirar a coisa da posse de quem a detém, sem violência ou grave ameaça."},{"termo":"Furto privilegiado","significado":"Furto de pequeno valor por réu primário, com benefícios na pena."}]'::jsonb, '["Art. 157 (roubo)","Art. 156","Art. 170"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-155'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Furto de coisa comum: subtrair o condômino, coerdeiro ou sócio, para si ou para outrem, a quem legitimamente a detém, a coisa comum. Pena: detenção de 6 meses a 2 anos, ou multa. Somente se procede mediante representação. Não é punível a subtração de coisa comum fungível cujo valor não excede a quota a que tem direito o agente.', '["Sujeito: condômino, coerdeiro ou sócio.","Subtrai coisa comum de quem legitimamente a detém.","Pena: detenção de 6 meses a 2 anos, ou multa.","Ação condicionada à representação.","Não é punível a subtração de coisa comum fungível até o valor da quota do agente."]'::jsonb, '["A coisa é COMUM (do próprio agente em parte)."]'::jsonb, 'Um sócio retira de quem a guarda mercadoria que pertence à sociedade, acima da sua quota.', '["Assertiva que pune a subtração de coisa comum fungível cujo valor não excede a quota do agente erra: o §2º a declara não punível."]'::jsonb, '[{"termo":"Coisa fungível","significado":"Coisa que pode ser substituída por outra do mesmo gênero, quantidade e qualidade, como dinheiro."}]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-156'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Roubo: subtrair coisa móvel alheia, para si ou para outrem, mediante grave ameaça ou violência a pessoa, ou depois de havê-la, por qualquer meio, reduzido à impossibilidade de resistência. Pena: reclusão de 6 a 10 anos e multa (texto atual). Aumento de 1/3 até metade (§2º) em hipóteses como concurso de duas ou mais pessoas, vítima em serviço de transporte de valores, manutenção da vítima em poder do agente, subtração de explosivos, emprego de arma branca, subtração de certos bens (fios e cabos, celulares e computadores, armas de fogo, combustíveis). Aumento de 2/3 (§2º-A): arma de fogo, ou destruição de obstáculo com explosivo. Se a arma é de uso restrito ou proibido, pena em dobro (§2º-B). Roubo qualificado pelo resultado (§3º): lesão grave: reclusão de 7 a 18 anos e multa; morte (latrocínio): reclusão de 24 a 30 anos e multa.', '["Caput: grave ameaça, violência ou redução à impossibilidade de resistência; reclusão de 6 a 10 anos e multa.","§2º: aumento de 1/3 até metade (concurso de pessoas; transporte de valores; vítima mantida em poder do agente; explosivos; arma branca; certos bens).","§2º-A: aumento de 2/3 (arma de fogo; explosivo para romper obstáculo).","§2º-B: arma de fogo de uso restrito ou proibido: pena em dobro.","§3º, I: lesão grave: reclusão de 7 a 18 anos e multa.","§3º, II: morte: reclusão de 24 a 30 anos e multa.","§4º e §5º: formas com organização ultraviolenta, paramilitar ou milícia (pena em triplo; reclusão de 20 a 40 anos se há morte)."]'::jsonb, '["Roubo = subtração + VIOLÊNCIA, GRAVE AMEAÇA ou redução da resistência.","Latrocínio (§3º, II) é o roubo com resultado MORTE e é crime hediondo.","Arma de fogo: aumento de 2/3 (§2º-A); arma branca: aumento de 1/3 a metade (§2º, VII); arma de fogo de uso restrito ou proibido: dobro (§2º-B)."]'::jsonb, 'Assaltante rende a vítima com uma arma de fogo e leva seu celular: roubo com aumento de 2/3 (e, conforme o texto, também causa de aumento pelo objeto).', '["Assertiva que aplica aumento de metade ao roubo com arma de fogo troca o percentual: o §2º-A fixa 2/3."]'::jsonb, '[{"termo":"Latrocínio","significado":"Roubo seguido de morte (art. 157, §3º, II)."}]'::jsonb, '["Art. 155","Art. 158 (extorsão)","Lei dos crimes hediondos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-157'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extorsão: constranger alguém, mediante violência ou grave ameaça, e com o intuito de obter indevida vantagem econômica, a fazer, tolerar que se faça ou deixar de fazer alguma coisa. Pena: reclusão de 4 a 10 anos e multa. Aumenta-se de um terço até metade se por duas ou mais pessoas ou com arma. Aplica-se à extorsão com violência o disposto no §3º do art. 157. Se o crime é cometido mediante restrição da liberdade da vítima, e essa condição é necessária para a vantagem econômica (sequestro-relâmpago), a pena é de reclusão de 6 a 12 anos, além da multa; se resulta lesão grave ou morte, aplicam-se as penas do art. 159, §§2º e 3º. Organização criminosa ultraviolenta, paramilitar ou milícia: pena em triplo.', '["Constranger com violência ou grave ameaça para obter vantagem econômica indevida.","Caput: reclusão de 4 a 10 anos e multa.","§1º: duas ou mais pessoas ou arma: aumento de 1/3 até metade.","§3º: restrição da liberdade da vítima necessária para a vantagem (sequestro-relâmpago): 6 a 12 anos; lesão grave ou morte: penas do art. 159, §§2º e 3º.","§4º: organização ultraviolenta, paramilitar ou milícia: pena em triplo."]'::jsonb, '["Extorsão: a colaboração da vítima é necessária (ela faz, tolera ou deixa de fazer); no roubo a subtração ocorre sem tal colaboração.","Sequestro-relâmpago: §3º, com pena de 6 a 12 anos."]'::jsonb, 'O agente ameaça o dono de um comércio, exigindo dinheiro periódico para não lhe causar mal: extorsão.', '["Assertiva que dispensa a finalidade de vantagem econômica na extorsão erra: é elementar do tipo."]'::jsonb, '[{"termo":"Sequestro-relâmpago","significado":"Restrição da liberdade da vítima por pouco tempo para obter vantagem econômica."}]'::jsonb, '["Art. 157","Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-158'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extorsão mediante sequestro: sequestrar pessoa com o fim de obter, para si ou para outrem, qualquer vantagem, como condição ou preço do resgate. Pena: reclusão de 8 a 15 anos. Se resulta lesão grave: reclusão de 16 a 24 anos; se resulta morte, pena maior, conforme o texto completo (o texto traz a indicação ''Vide Lei nº 8.072/90''). No concurso, o concorrente que denunciar à autoridade, facilitando a libertação do sequestrado, tem pena reduzida de um a dois terços. Se o crime é cometido por integrante de organização criminosa ultraviolenta, paramilitar ou milícia, aumenta-se a pena em 2/3.', '["Sequestrar pessoa para obter qualquer vantagem como condição ou preço do resgate.","Caput: reclusão de 8 a 15 anos.","§2º: lesão grave: reclusão de 16 a 24 anos.","§3º: morte (pena maior).","§4º: delação premiada: redução de 1/3 a 2/3 ao concorrente que denunciar e facilitar a libertação.","§5º: organização ultraviolenta, paramilitar ou milícia: aumento de 2/3."]'::jsonb, '["Vantagem de QUALQUER natureza (não só econômica).","É crime hediondo (lei especial).","§4º: delação eficaz reduz a pena de um a dois terços."]'::jsonb, 'Sequestradores exigem pagamento da família para libertar a vítima: art. 159.', '["Assertiva que exige vantagem econômica no art. 159 erra: o texto fala em qualquer vantagem."]'::jsonb, '[]'::jsonb, '["Art. 148","Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-159'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extorsão indireta: exigir ou receber, como garantia de dívida, abusando da situação de alguém, documento que pode dar causa a procedimento criminal contra a vítima ou contra terceiro. Pena: reclusão de 1 a 3 anos e multa.', '["Exigir ou receber documento como garantia de dívida.","Abusando da situação de alguém.","Documento que pode dar causa a procedimento criminal.","Reclusão de 1 a 3 anos e multa."]'::jsonb, '["Típico do ''agiota'' que exige documento comprometedor como garantia."]'::jsonb, 'O credor exige, como garantia da dívida, um documento que pode incriminar o devedor.', '["Assertiva que dispensa o abuso da situação da vítima no art. 160 erra: é parte do tipo."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-160'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Alteração de limites, usurpação de águas e esbulho possessório: suprimir ou deslocar tapume, marco ou outro sinal de linha divisória para apropriar-se de coisa imóvel alheia. Pena: detenção de 1 a 6 meses e multa. Na mesma pena quem desvia ou represa águas alheias em proveito próprio ou de outrem, ou invade, com violência a pessoa ou grave ameaça, ou mediante concurso de mais de duas pessoas, terreno ou edifício alheio para esbulho possessório. Se há violência, pune-se também a violência. Se a propriedade é particular e sem violência, somente se procede mediante queixa.', '["Caput: suprimir ou deslocar marco divisório para apropriar-se de imóvel.","§1º, I: usurpação de águas.","§1º, II: esbulho possessório (violência, grave ameaça ou mais de duas pessoas).","§2º: também a pena da violência.","§3º: propriedade particular e sem violência: queixa."]'::jsonb, '["Concurso de MAIS DE DUAS pessoas no esbulho (inciso II)."]'::jsonb, 'Grupo de mais de duas pessoas invade terreno alheio para se apossar dele: esbulho possessório (§1º, II).', '["Assertiva que exige apenas duas pessoas para o esbulho do §1º, II, erra: exige mais de duas."]'::jsonb, '[{"termo":"Esbulho possessório","significado":"Invasão de imóvel para tomar-lhe a posse."}]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-161'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Supressão ou alteração de marca em animais: suprimir ou alterar, indevidamente, em gado ou rebanho alheio, marca ou sinal indicativo de propriedade. Pena: detenção de 6 meses a 3 anos e multa.', '["Suprimir ou alterar marca ou sinal de propriedade em gado ou rebanho alheio.","Detenção de 6 meses a 3 anos e multa."]'::jsonb, '["O objeto é a MARCA (sinal indicativo de propriedade), não a subtração do animal."]'::jsonb, 'Alterar a marca a ferro em bois alheios para dificultar a identificação do dono.', '["Assertiva que aplica o art. 162 à simples subtração de animal erra: ele pune a supressão ou alteração da marca."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-162'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dano: destruir, inutilizar ou deteriorar coisa alheia. Pena: detenção de 1 a 6 meses, ou multa. Dano qualificado (detenção de 6 meses a 3 anos e multa, além da pena da violência) quando cometido com violência à pessoa ou grave ameaça; com emprego de substância inflamável ou explosiva, se o fato não constitui crime mais grave; ou por motivo egoístico ou com prejuízo considerável para a vítima. Confira o texto completo para as demais hipóteses de dano qualificado.', '["Caput: destruir, inutilizar ou deteriorar coisa alheia: detenção de 1 a 6 meses, ou multa.","Parágrafo único: qualificadoras (violência ou grave ameaça; substância inflamável ou explosiva; motivo egoístico ou prejuízo considerável).","Pena do dano qualificado: detenção de 6 meses a 3 anos e multa, além da violência."]'::jsonb, '["Dano exige DOLO de destruir/inutilizar/deteriorar; não há dano culposo.","A coisa deve ser ALHEIA."]'::jsonb, 'Quebrar de propósito o vidro do carro do vizinho: dano.', '["Assertiva que pune o dano culposo erra: o crime só existe na forma dolosa."]'::jsonb, '[]'::jsonb, '["Art. 167 (ação penal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-163'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Introdução ou abandono de animais em propriedade alheia: introduzir ou deixar animais em propriedade alheia, sem consentimento de quem de direito, desde que do fato resulte prejuízo. Pena: detenção de 15 dias a 6 meses, ou multa.', '["Introduzir ou deixar animais em propriedade alheia sem consentimento.","Exige prejuízo.","Detenção de 15 dias a 6 meses, ou multa."]'::jsonb, '["Só há crime se resultar PREJUÍZO."]'::jsonb, 'Soltar o gado no pasto do vizinho, que sofre prejuízo.', '["Assertiva que dispensa o prejuízo no art. 164 erra: é condição do tipo."]'::jsonb, '[]'::jsonb, '["Art. 167"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-164'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dano em coisa de valor artístico, arqueológico ou histórico: destruir, inutilizar ou deteriorar coisa tombada pela autoridade competente em virtude de valor artístico, arqueológico ou histórico. Pena: detenção de 6 meses a 2 anos e multa.', '["Coisa tombada pela autoridade competente.","Valor artístico, arqueológico ou histórico.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["A coisa deve ser TOMBADA pela autoridade."]'::jsonb, 'Pichar um monumento tombado como patrimônio histórico.', '["Assertiva que aplica o art. 165 a bens sem tombamento erra."]'::jsonb, '[{"termo":"Tombamento","significado":"Proteção oficial de bens de valor cultural."}]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
