insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ação penal: nos casos do art. 163 (dano simples), do inciso IV do seu parágrafo (dano por motivo egoístico ou com prejuízo considerável) e do art. 164, somente se procede mediante queixa.', '["Ação penal privada nos arts. 163 (simples), 163, parágrafo único, IV, e 164."]'::jsonb, '["As demais qualificadoras do dano (violência, substância inflamável) são de ação pública."]'::jsonb, 'No dano simples, a vítima precisa oferecer queixa.', '["Assertiva que torna pública incondicionada a ação no dano simples erra: é por queixa."]'::jsonb, '[]'::jsonb, '["Arts. 163 e 164"]'::jsonb, 'under_review', 'claude'
