insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apropriação indébita: apropriar-se de coisa alheia móvel, de que tem a posse ou a detenção. Pena: reclusão de 1 a 4 anos e multa. A pena aumenta-se de um terço quando o agente recebeu a coisa em depósito necessário; na qualidade de tutor, curador, síndico, liquidatário, inventariante, testamenteiro ou depositário judicial; ou em razão de ofício, emprego ou profissão.', '["O agente JÁ tem a posse ou detenção legítima e inverte o ânimo, apropriando-se.","Pena: reclusão de 1 a 4 anos e multa.","§1º: aumento de 1/3 (depósito necessário; tutor, curador, síndico, liquidatário, inventariante, testamenteiro ou depositário judicial; ofício, emprego ou profissão)."]'::jsonb, '["Diferença para o furto: na apropriação indébita a posse é LEGÍTIMA no início; no furto há subtração."]'::jsonb, 'O depositário de um bem se recusa a devolvê-lo e passa a tratá-lo como seu: apropriação indébita.', '["Assertiva que exige subtração da coisa na apropriação indébita erra: o agente já tem a posse ou detenção."]'::jsonb, '[]'::jsonb, '["Art. 155","Art. 168-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-168'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apropriação indébita previdenciária: deixar de repassar à previdência social as contribuições recolhidas dos contribuintes, no prazo e forma legal ou convencional. Pena: reclusão de 2 a 5 anos e multa. Na mesma pena quem deixa de recolher no prazo contribuição descontada de pagamento a segurados, a terceiros ou arrecadada do público; de recolher contribuições que integraram despesas contábeis ou custos relativos à venda de produtos ou prestação de serviços; ou de pagar benefício devido a segurado quando já reembolsado pela previdência. É extinta a punibilidade se o agente espontaneamente declara, confessa e paga antes do início da ação fiscal. O juiz pode deixar de aplicar a pena ou aplicar só a multa se o agente é primário e de bons antecedentes, em hipóteses do §3º. Os §§5º e 6º, incluídos em 2026, afastam a extinção de punibilidade do §2º para o devedor contumaz declarado em decisão administrativa definitiva e inscrito no Cadin.', '["Caput: não repassar contribuições recolhidas: reclusão de 2 a 5 anos e multa.","§1º: não recolher contribuição descontada; contribuições embutidas em custos; não pagar benefício já reembolsado.","§2º: extinção da punibilidade com declaração, confissão e pagamento antes da ação fiscal.","§3º: perdão judicial ou multa (primário e bons antecedentes) com pagamento ou valor mínimo.","§§5º e 6º: devedor contumaz inscrito no Cadin não tem a extinção do §2º."]'::jsonb, '["Extinção da punibilidade só com pagamento ANTES do início da ação fiscal.","O devedor contumaz declarado e inscrito no Cadin não se beneficia do §2º (texto atual)."]'::jsonb, 'Empresa desconta a contribuição previdenciária do salário e não a repassa à previdência: art. 168-A.', '["Assertiva que permite extinguir a punibilidade mesmo após o início da ação fiscal erra: o §2º exige pagamento antes dela."]'::jsonb, '[{"termo":"Cadin","significado":"Cadastro Informativo dos créditos não quitados do setor público federal."}]'::jsonb, '["Art. 168"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-168-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apropriação de coisa havida por erro, caso fortuito ou força da natureza: apropriar-se alguém de coisa alheia vinda ao seu poder por erro, caso fortuito ou força da natureza. Pena: detenção de 1 mês a 1 ano, ou multa. Na mesma pena quem acha tesouro em prédio alheio e se apropria, no todo ou em parte, da quota do proprietário do prédio, e quem acha coisa alheia perdida e dela se apropria, total ou parcialmente, deixando de restituí-la ao dono ou legítimo possuidor ou de entregá-la à autoridade competente no prazo de 15 dias.', '["Caput: coisa que chegou por erro, caso fortuito ou força da natureza.","Parágrafo único, I: apropriação de tesouro (quota do dono do prédio).","Parágrafo único, II: apropriação de coisa achada: prazo de 15 dias para restituir ou entregar à autoridade.","Detenção de 1 mês a 1 ano, ou multa."]'::jsonb, '["Coisa achada: 15 dias para devolver ou entregar à autoridade."]'::jsonb, 'Quem encontra uma carteira com documentos e a guarda sem procurar o dono nem entregar à autoridade em 15 dias comete o crime.', '["Assertiva que fixa em 30 dias o prazo para entregar a coisa achada erra: são 15 dias."]'::jsonb, '[{"termo":"Tesouro","significado":"Depósito antigo de coisas preciosas, sem dono conhecido."}]'::jsonb, '["Art. 168"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-169'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes previstos neste capítulo (crimes contra o patrimônio da apropriação indébita, entre outros), aplica-se o disposto no art. 155, §2º, isto é, o privilégio (primário e de pequeno valor).', '["Extensão do furto privilegiado (art. 155, §2º) aos crimes do capítulo (apropriação indébita, estelionato etc.)."]'::jsonb, '["O privilégio exige primariedade e coisa de pequeno valor."]'::jsonb, 'Em apropriação indébita de objeto de pequeno valor por réu primário, o juiz pode reduzir a pena nos termos do art. 155, §2º.', '["Assertiva que nega o privilégio do furto aos crimes de apropriação erra: o art. 170 o estende."]'::jsonb, '[]'::jsonb, '["Art. 155, §2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-170'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estelionato: obter, para si ou para outrem, vantagem ilícita, em prejuízo alheio, induzindo ou mantendo alguém em erro, mediante artifício, ardil ou qualquer outro meio fraudulento. Pena: reclusão de 1 a 5 anos e multa (texto atual). Se primário e de pequeno valor o prejuízo, aplica-se o art. 155, §2º. Nas mesmas penas incorre quem pratica as fraudes do §2º: disposição de coisa alheia como própria; alienação ou oneração fraudulenta de coisa própria; defraudação de penhor; fraude na entrega de coisa; fraude para recebimento de seguro; fraude no pagamento por cheque sem provisão de fundos; e cessão de conta bancária para fins criminosos (conta laranja). Fraude eletrônica (§2º-A): reclusão de 4 a 8 anos e multa; aumento de 1/3 a 2/3 se servidor fora do país. Aumento de um terço contra entidade de direito público ou de assistência social (§3º), e de 1/3 ao dobro contra idoso ou vulnerável (§4º).', '["Caput: vantagem ilícita em prejuízo alheio, induzindo ou mantendo em erro, por fraude; reclusão de 1 a 5 anos e multa.","§1º: privilégio (primário e pequeno valor).","§2º, I a VII: fraudes equiparadas (coisa alheia como própria; coisa própria inalienável; penhor; entrega de coisa; seguro; cheque sem fundos; conta laranja).","§2º-A: fraude eletrônica: reclusão de 4 a 8 anos e multa.","§2º-B: servidor fora do país: aumento de 1/3 a 2/3.","§3º: aumento de 1/3 contra entidade de direito público, economia popular, assistência social ou beneficência.","§4º: aumento de 1/3 ao dobro contra idoso ou vulnerável."]'::jsonb, '["Estelionato exige FRAUDE e erro da vítima, que entrega voluntariamente a vantagem (diferente do furto e do roubo).","O §5º, sobre a ação penal, está revogado no texto atual.","A fraude eletrônica do §2º-A tem pena de 4 a 8 anos."]'::jsonb, 'Vender, por meio de anúncio falso na internet, um produto que não existe, recebendo o pagamento: estelionato.', '["Assertiva que dispensa o emprego de fraude no estelionato erra: o meio fraudulento é elementar."]'::jsonb, '[{"termo":"Ardil","significado":"Astúcia, manobra para enganar alguém."}]'::jsonb, '["Art. 155","Art. 170"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-171'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraude com ativos virtuais, valores mobiliários ou ativos financeiros: organizar, gerir, ofertar ou distribuir carteiras ou intermediar operações que envolvam ativos virtuais, valores mobiliários ou quaisquer ativos financeiros com o fim de obter vantagem ilícita, em prejuízo alheio, induzindo ou mantendo alguém em erro, mediante artifício, ardil ou qualquer outro meio fraudulento. Pena: reclusão de 4 a 8 anos e multa. (Na plataforma, o texto desta unidade vem seguido da duplicata simulada, com pena de detenção de 2 a 4 anos e multa, e seu parágrafo único sobre falsificação da escrituração do Livro de Registro de Duplicatas.)', '["Organizar, gerir, ofertar, distribuir carteiras ou intermediar operações com ativos virtuais, valores mobiliários ou ativos financeiros.","Fim de obter vantagem ilícita, em prejuízo alheio, com fraude.","Pena: reclusão de 4 a 8 anos e multa.","O texto exibido a seguir traz a duplicata simulada: detenção de 2 a 4 anos e multa."]'::jsonb, '["O tipo exige fraude e indução em erro (como no estelionato).","A duplicata simulada é crime autônomo, cujo texto aparece junto a esta unidade."]'::jsonb, 'Oferecer investimento em criptomoedas prometendo lucros certos para enganar clientes.', '["Assertiva que dispensa a fraude para configurar o art. 171-A erra."]'::jsonb, '[{"termo":"Ativo virtual","significado":"Representação digital de valor negociável (como criptoativos)."}]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-171-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abuso de incapazes: abusar, em proveito próprio ou alheio, de necessidade, paixão ou inexperiência de menor, ou da alienação ou debilidade mental de outrem, induzindo qualquer deles à prática de ato suscetível de produzir efeito jurídico, em prejuízo próprio ou de terceiro. Pena: reclusão de 2 a 6 anos e multa.', '["Abusar da necessidade, paixão ou inexperiência de menor, ou da alienação ou debilidade mental.","Induzir à prática de ato com efeito jurídico em prejuízo próprio ou de terceiro.","Reclusão de 2 a 6 anos e multa."]'::jsonb, '["A vítima é MENOR ou pessoa com alienação ou debilidade mental."]'::jsonb, 'Fazer pessoa com debilidade mental assinar um contrato que a prejudica.', '["Assertiva que aplica o art. 173 a qualquer vítima adulta capaz erra."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-173'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Induzimento à especulação: abusar, em proveito próprio ou alheio, da inexperiência ou da simplicidade ou inferioridade mental de outrem, induzindo-o à prática de jogo ou aposta, ou à especulação com títulos ou mercadorias, sabendo ou devendo saber que a operação é ruinosa. Pena: reclusão de 1 a 3 anos e multa.', '["Abusar da inexperiência, simplicidade ou inferioridade mental.","Induzir a jogo, aposta ou especulação com títulos ou mercadorias.","Operação sabidamente ruinosa.","Reclusão de 1 a 3 anos e multa."]'::jsonb, '["Exige que o agente SAIBA ou DEVA SABER que a operação é ruinosa."]'::jsonb, 'Convencer pessoa ingênua a investir suas economias em uma operação que sabe ser ruinosa.', '["Assertiva que dispensa o conhecimento do caráter ruinoso da operação erra."]'::jsonb, '[]'::jsonb, '["Art. 171","Art. 173"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-174'
