insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Outras fraudes: tomar refeição em restaurante, alojar-se em hotel ou utilizar-se de meio de transporte sem dispor de recursos para efetuar o pagamento. Pena: detenção de 15 dias a 2 meses, ou multa. Somente se procede mediante representação, e o juiz pode, conforme as circunstâncias, deixar de aplicar a pena.', '["Consumir refeição, hospedagem ou transporte sem recursos para pagar.","Detenção de 15 dias a 2 meses, ou multa.","Ação condicionada à representação.","O juiz pode deixar de aplicar a pena."]'::jsonb, '["Hipótese conhecida como ''calote''; ação condicionada à representação."]'::jsonb, 'Pessoa almoça em restaurante sabendo que não tem dinheiro para pagar.', '["Assertiva que torna incondicionada a ação do art. 176 erra: exige representação."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-176'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraudes e abusos na fundação ou administração de sociedade por ações: promover a fundação de sociedade por ações fazendo, em prospecto ou comunicação ao público ou à assembleia, afirmação falsa sobre a constituição da sociedade, ou ocultando fraudulentamente fato a ela relativo. Pena: reclusão de 1 a 4 anos e multa, se o fato não constitui crime contra a economia popular. Na mesma pena incorrem diretor, gerente ou fiscal que faz afirmação falsa sobre as condições econômicas da sociedade, promove falsa cotação das ações, toma empréstimo à sociedade ou usa bens sociais sem autorização da assembleia, compra ou vende ações da própria sociedade fora dos casos permitidos, ou aceita em penhor ou caução ações da própria sociedade como garantia de crédito social.', '["Falsa afirmação ou ocultação fraudulenta na fundação de sociedade por ações.","Pena: reclusão de 1 a 4 anos e multa, se não for crime contra a economia popular.","§1º, I a V: condutas de diretor, gerente ou fiscal (afirmação falsa; falsa cotação; uso de bens da sociedade; negociação de ações próprias; aceitar ações próprias em penhor)."]'::jsonb, '["Subsidiário ao crime contra a economia popular (ressalva expressa)."]'::jsonb, 'O diretor promove falsa cotação das ações da companhia para atrair investidores.', '["Assertiva que aplica o art. 177 mesmo quando o fato constitui crime contra a economia popular erra: a ressalva afasta o tipo."]'::jsonb, '[{"termo":"Prospecto","significado":"Documento de oferta pública de valores mobiliários."}]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
