insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Receptação: adquirir, receber, transportar, conduzir ou ocultar, em proveito próprio ou alheio, coisa que sabe ser produto de crime, ou influir para que terceiro, de boa-fé, a adquira, receba ou oculte. Pena: reclusão de 2 a 6 anos e multa (texto atual). Receptação qualificada (§1º): no exercício de atividade comercial ou industrial, coisa que deve saber ser produto de crime (reclusão de 3 a 8 anos e multa), e o §2º equipara à atividade comercial qualquer forma de comércio irregular ou clandestino, inclusive em residência. Receptação culposa (§3º): adquirir ou receber coisa que, por sua natureza, pela desproporção entre valor e preço ou pela condição de quem a oferece, deve presumir-se obtida por meio criminoso: detenção de 1 mês a 1 ano, ou multa, ou ambas. A receptação é punível ainda que desconhecido ou isento de pena o autor do crime anterior (§4º). Bens de entes públicos: pena em dobro (§6º); fios, cabos e equipamentos de energia, telefonia, dados ou cargas ferroviárias ou metroviárias: em dobro (§7º).', '["Caput: sabe ser produto de crime; reclusão de 2 a 6 anos e multa.","§1º: qualificada (atividade comercial ou industrial; ''deve saber''): reclusão de 3 a 8 anos e multa.","§2º: comércio irregular ou clandestino, inclusive em residência, equipara-se à atividade comercial.","§3º: culposa (deve presumir-se obtida por meio criminoso): detenção de 1 mês a 1 ano, ou multa, ou ambas.","§4º: punível ainda que o autor do crime anterior seja desconhecido ou isento de pena.","§6º: bens da União, Estados, DF, Municípios e entes públicos: pena em dobro.","§7º: fios, cabos, equipamentos e cargas citados: pena em dobro."]'::jsonb, '["Caput exige DOLO DIRETO (''sabe ser produto de crime''); no §1º basta ''deve saber''.","Receptação CULPOSA: §3º, com pena de detenção.","A receptação é crime AUTÔNOMO: independe da punição do autor do crime antecedente (§4º)."]'::jsonb, 'Quem compra, por preço muito abaixo do mercado, celular oferecido por desconhecido na rua pode responder por receptação culposa (§3º).', '["Assertiva que exige a condenação do autor do crime anterior para punir a receptação erra: o §4º a dispensa."]'::jsonb, '[{"termo":"Receptação","significado":"Lidar com coisa que se sabe (ou deve saber) ser produto de crime."}]'::jsonb, '["Art. 180-A","Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-180'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Receptação de animais: adquirir, receber, transportar, conduzir, ocultar, ter em depósito ou vender, com a finalidade de produção ou comercialização, semovente domesticável de produção, ainda que abatido ou dividido em partes, ou animal doméstico, que sabe ou deve saber ser produto de crime. Pena: reclusão de 3 a 8 anos e multa (texto atual).', '["Objeto: semovente domesticável de produção (mesmo abatido ou dividido em partes) ou animal doméstico.","Finalidade de produção ou comercialização.","Sabe ou deve saber que é produto de crime.","Reclusão de 3 a 8 anos e multa."]'::jsonb, '["Basta ''sabe ou deve saber''."]'::jsonb, 'Frigorífico recebe gado abatido de origem criminosa para comercializar.', '["Assertiva que exige finalidade de lucro direto para o crime erra: o tipo fala em finalidade de produção ou comercialização."]'::jsonb, '[{"termo":"Semovente","significado":"Animal que se move por si, como o gado."}]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-180-a'
