insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atentado contra a liberdade de trabalho: constranger alguém, mediante violência ou grave ameaça, a exercer ou não exercer arte, ofício, profissão ou indústria, ou a trabalhar ou não trabalhar durante certo período ou em determinados dias (detenção de 1 mês a 1 ano e multa, além da pena da violência); ou a abrir ou fechar o seu estabelecimento de trabalho, ou a participar de parede ou paralisação de atividade econômica (detenção de 3 meses a 1 ano e multa, além da violência).', '["I – constranger a exercer ou não exercer profissão ou a trabalhar ou não: detenção de 1 mês a 1 ano e multa.","II – constranger a abrir ou fechar estabelecimento ou a participar de greve ou paralisação: detenção de 3 meses a 1 ano e multa.","Em ambos, além da pena da violência."]'::jsonb, '["Exige violência ou grave ameaça."]'::jsonb, 'Ameaçar um comerciante para que feche o estabelecimento em dia de paralisação.', '["Assertiva que dispensa violência ou grave ameaça no art. 197 erra."]'::jsonb, '[]'::jsonb, '["Arts. 198 a 200"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-197'
