insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atentado contra a liberdade de contrato de trabalho e boicotagem violenta: constranger alguém, mediante violência ou grave ameaça, a celebrar contrato de trabalho, ou a não fornecer a outrem ou não adquirir de outrem matéria-prima ou produto industrial ou agrícola. Pena: detenção de 1 mês a 1 ano e multa, além da pena da violência.', '["Constranger a celebrar contrato de trabalho.","Ou a não fornecer ou não adquirir matéria-prima ou produto (boicote violento).","Detenção de 1 mês a 1 ano, multa e pena da violência."]'::jsonb, '["Boicotagem violenta: coação para não fornecer ou não comprar."]'::jsonb, 'Ameaçar um fornecedor para que deixe de vender a um concorrente.', '["Assertiva que torna lícita a boicotagem pacífica como crime erra: o tipo exige violência ou grave ameaça."]'::jsonb, '[]'::jsonb, '["Art. 197"]'::jsonb, 'under_review', 'claude'
