insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Paralisação de trabalho seguida de violência ou perturbação da ordem: participar de suspensão ou abandono coletivo de trabalho, praticando violência contra pessoa ou contra coisa. Pena: detenção de 1 mês a 1 ano e multa, além da pena da violência. Para considerar-se coletivo, o abandono exige o concurso de, pelo menos, três empregados.', '["Participar de suspensão ou abandono coletivo de trabalho com violência contra pessoa ou coisa.","Detenção de 1 mês a 1 ano, multa e pena da violência.","Parágrafo único: mínimo de TRÊS empregados."]'::jsonb, '["A greve em si não é crime; o crime é a violência na paralisação.","Coletivo = pelo menos três empregados."]'::jsonb, 'Em uma greve, grupo de trabalhadores depreda máquinas da empresa.', '["Assertiva que considera crime a mera adesão pacífica à greve erra: o tipo exige violência."]'::jsonb, '[]'::jsonb, '["Art. 201"]'::jsonb, 'under_review', 'claude'
